	var abbrev
	function handleprefix(name,prefix){
		if (name == null) return null
		if (name == '') return ''
		var newname
		if ((name.length > 5) && /^[A-Z]{4}_.*/.test(name)) {
			newname = name.replace(/^[A-Z]{4}_/,abbrev+'_')
			//message(name+':'+/^[A-Z]{4}_.*/.test(name))
		} else {
			if (!newname.starstWith(abbrev))
			newname = abbrev+'_'+name
		}
		return newname
	}

	function do1table(table){
		var cols = table.getElements();
		abbrev = table.getAbbreviation();
		if (abbrev == null) return;
		if (abbrev == '') return;
		//if (abbrev != 'LANG') return;

		keys = table.getKeys()
		for (var k = 0; k < keys.length; k++){
			var key = keys[k]
			//message(abbrev+':'+key.getName())
			key.setName(handleprefix(key.getName(),abbrev))
		}
//		keys = table.getUKeys()
//		for (var k = 0; k < keys.length; k++){
//			key = keys[k]
//			message(abbrev+':'+key.getName())
//			key.setName(handleprefix(key.getName(),abbrev))
//		}

		var checks = table.getCheckConstraints()
		for (var cc = 0; cc < checks.length; cc++){
			var check = checks[cc]
			//message(abbrev+':'+check.getName())
			check.setName(handleprefix(check.getName(),abbrev))
		}

		//message(table.getName()+'/'+abbrev);
		for (var c = 0; c < cols.length; c++){
			var col = cols[c]
			var colname = col.getName()
			//message(colname+':'+/^[A-Z]{4}_.*/.test(colname)+':'+colname.length+':'+col.getConstraintName())
			colname = handleprefix(colname,abbrev)
			var constrName = handleprefix(col.getConstraintName(),abbrev)
			//message(colname+':'+constrName)			
			col.setName(colname)
			col.setConstraintName(constrName)
		}
		table.setDirty(true)
	}
var tables = model.getTableSet().toArray();
//message(model.getName()+':'+tables.length)
for (var t = 0; t<tables.length;t++){
	do1table(tables[t]);
}

			// columns are found by column name
// allowing reuse of already existing columns
// dynamic property ctemplateID is set afterwards - will keep connection to template
// column even if the name of column is changed
var t_name = "table_template";
var p_name = "ctemplateID";
template = model.getTableSet().getByName(t_name);
if(template!=null){
    tcolumns = template.getElements();
    tables = model.getTableSet().toArray();
    for (var t = 0; t<tables.length;t++){
     table = tables[t];
    // compare name ignoring the case
     if(!table.getName().equalsIgnoreCase(t_name)){
         for (var i = 0; i < tcolumns.length; i++) {
            column = tcolumns[i];
            col = table.getElementByName(column.getName());
            if(col==null){
             col = table.getColumnByProperty(p_name,column.getObjectID());
            }
            if(col==null){
             col = table.createColumn();
            }
            column.copy(col);
            //set property after copy otherwise it'll be cleared by copy
            col.setProperty(p_name,column.getObjectID());
            table.setDirty(true);
         }
     }
    }
}

