			var CODEVERSION = "3.0";
			var FORMATJSON = "JSON";
			var FORMATCSV = "CSV"
			var g_tabanz = 0;
			var g_colanz = 0;
			var g_colmapanz = 0
			var g_tabmapanz = 0
			var g_lineanz = 0
			var g_logicalModel
			var g_entitySet
			var g_relationSet
			var g_inheritanceSet
			var g_rmodels
			var g_writtenCols = {}
			var g_exportDirec = java.lang.System.getProperty("user.home") +"/Downloads" 
			var g_importDirec = java.lang.System.getProperty("user.home") +"/Downloads"
			var EXTIDPROPNAME = "EXT_ATTR_ID"
			var EXCELCSVSEP = ";"
			var EXCELESCCHAR = '"'
			var EXCELMULTILINESEP = String.fromCharCode(10)
			var EXCELLINEEND = String.fromCharCode(10)
			var EXCELBOM = "\ufeff" //String.fromCharCode(0xef,0xbb,0xbf)

			// Types for mapping element
			ENTITYPE = 0
			COLTYPE = 5
			TABLETYPE = 4
			ATTRTYPE = 1
			RELATYPE = 3 //(source ent, targ ent)
			FKTYPE = 8
			INHERITTYPE = 9
			RELARCTYPE = 13
			LOGARCTYPE = 14
