			function getColName(rmod, tabID, colID) {
				tab = rmod.getTableSet().getObjectByID(tabID)
				col = tab.getElementByID(colID)
				return tab + '.' + col
			}

			function colProperty(pcurmodel, tabname, colname, propName) {
				table = pcurmodel.getTableSet().getByName(tabName);
				if (table == null) return ""
				column = table.getElementByName(colName);
				extID = column.getProperty(propName)
				return ((extID == null) || (extID == ".")) ? "" : extID
			}

			function findFK(fks, fkID) {
				for (iloc in fks) {
					//		if (fkID == "8AEA1CA4-3B90-4F1D-37AE-8A0FD50F8996") {message(fks[iloc].getTable()+fks[iloc].getObjectID()+fks[iloc])}
					if (fks[iloc].getObjectID() == fkID) return fks[iloc]
				}
				return null
			}

			function tabList(maps, elemType, pcurmodel) {
				tlretval = []
				if (maps != null) {
					if (elemType != 'Entity') {
						fks = pcurmodel.getFKIndexAssociationSet().toArray()
					}
					for (i in maps) {
						if (elemType == 'Entity') {
							tabName = maps[i].tableName
						} else {
							fk = findFK(fks, maps[i].relID)
							if (fk != null) {
								tabName = fk.getTable()
							} else {
								tabName = maps[i].tableName // falls es m:n ist ist es eine Table
							}
						}
						tlretval.push(tabName.getName())
					}
				}
				//message('tablist= '+tlretval+ '|'+elemType)
				return tlretval
			}

			function elements(rmodels, logID, elemType, nurX) {
				elretval = []
				for (ih = 0; ih < rmodels.length; ih++) {
					var curmodel = rmodels[ih]
					maps = getLogMap(logID, curmodel)
					if (maps.length > 0) {
						if (nurX) {
							elretval.push(['X'])
						} else {
							elretval.push(tabList(maps, elemType, curmodel), [], [])
						}
					} else {
						if (nurX) {
							elretval.push([])
						} else {
							elretval.push([], [], [])
						}
					}
					// Extra columns are empty
				}
				return elretval
			}

			var g_curmodel = null // for the sortattrmaps function			
			function sortattrmaps(a,b){
				var atab = g_containerMappings[a.parentID].tableName
				var acol = g_curmodel.getTableSet().getByName(atab).getElementByID(a.relID)
				var btab = g_containerMappings[b.parentID].tableName
				var bcol = g_curmodel.getTableSet().getByName(btab).getElementByID(b.relID)
				if (atab < btab) {return -1 }
				if (atab > btab) {return 1}
				return (acol < bcol) ? -1 : (acol > bcol) ? 1 : 0
			}

			function attrElements(rmodels, attrID, nurX) {
				var aeretval = []
				var attrlist = []
				var tabNames = []
				var colNames = []
				var colIDs = []
				for (irmpm = 0; irmpm < rmodels.length; irmpm++) {
					g_curmodel = rmodels[irmpm]
					//linemessage('attrElements 1',rmodels.length,attrID,g_curmodel.getName())
					var attrmaps = getAttrMap(attrID, g_curmodel.getName())
						//		if (attrID == '55CABD5F-9462-BF35-239C-E8A1A1D0848C') {
						//			message(g_curmodel.getName()+':'+attrID+':'+attrmaps.length)
						//		}
					//linemessage('attrElements 2',attrmaps.length,g_curmodel.getName())
					if (attrmaps.length > 0) {
						if (nurX) {
							attrlist = [
								['X']
							]
						} else {
							attrlist = [],
							tabNames = []
							colNames = []
							colIDs = []
							//SORT
							var attrmaplist = []
							for (var key in attrmaps) {
							    attrmaplist.push( attrmaps[key] );
							}
							attrmaplist.sort(sortattrmaps);
							for (var amidx=0;amidx<attrmaplist.length;amidx++) {
								var attrmap = attrmaplist[amidx]
								//linemessage('attrElements 3',attrmap.parentID,attrmap.relID,g_curmodel.getName())
							//SORT
							//for (key in attrmaps) {
							//attrmap = attrmaps[key]
								tabName = g_containerMappings[attrmap.parentID].tableName
								colName = g_curmodel.getTableSet().getByName(tabName).getElementByID(attrmap.relID)
								tabNames.push(tabName.getName())
								colNames.push(colName.getName())
								colIDs.push(colProperty(g_curmodel, tabName, colName, EXTIDPROPNAME))
							}
							//				if (attrID == '55CABD5F-9462-BF35-239C-E8A1A1D0848C') {
							//					message('tabName1='+tabNames+'\ncolNames='+colNames+'\ncolIDs='+colIDs)
							//				}

							//tabNames = tabNames.slice(0, -1)
							//colNames = colNames.slice(0, -1)
							//colIDs = colIDs.slice(0, -1)
							attrlist = [tabNames, colNames, colIDs]
						}
					} else {
						attrlist = nurX ? [
							[]
						] : [
							[],
							[],
							[]
						]
					}
					aeretval = aeretval.concat(attrlist)
				}
				return aeretval
			}


			function logicalElement(rmodels, logElem, nurX) {
				var leretval = []
				var elemID = logElem.getObjectID()
				var attrs = null
				var entyentry 
				if (logElem.getObjectTypeName() == 'Entity') {
					entyentry = [logElem.getName(), '']
					entyentry = entyentry.concat(elements(rmodels, logElem.getObjectID(), logElem.getObjectTypeName(), nurX))
					leretval.push(entyentry)
					attrs = logElem.getElementsCollection().toArray()
				} else if (logElem.getObjectTypeName() == 'Relation') {
					if (logElem.isManyToMany()) { // FK-Mapping ist nicht trivial bei seltsamen Modellen
						entyentry = [logElem.getName(), '']
						entyentry = entyentry.concat(elements(rmodels, logElem.getObjectID(), logElem.getObjectTypeName(), nurX))
						leretval.push(entyentry)
						attrs = logElem.getAttributesCollection().toArray()
					}
				} else { // assume inheritance
					// Inheritance sind schon entities line += elements(rmodels,logElem.getObjectID(),logElem.getObjectTypeName(),nurX)
					// Inheritance becomes fk-columns
				}
				//message('logical Elements before attrs= '+logElem.getName()+'|'+leretval)
				if (attrs != null) {
					for (iattrac = 0; iattrac < attrs.length; iattrac++) {
						var attr = attrs[iattrac]
						var attrID = attr.getObjectID()
						var key = elemID + '.' + attrID
						attrentry = [logElem.getName(), attr.getName()] //DEBUG  ,attrID]
						attrentry = attrentry.concat(attrElements(rmodels, attrID, nurX))
						leretval.push(attrentry)
							//throw new Error("\nattrs: " + leretval + "\n");
					}
				}
				//message('logical Elements= '+logElem.getName()+'|'+leretval)
				return leretval
			}

			//	function printElementGroup(rmodels, group, nurX) {
			function mappings2json(rmodels, group, nurX) {
				m2jretval = []
				if (group != null) {
					for (ig = 0; ig < group.length; ig++) {
						m2jretval = m2jretval.concat(logicalElement(rmodels, group[ig], nurX))
					}
				}
				//message('mappings2json= '+retval)
				return m2jretval
			}

			function escapeexcelchars(s){
				var retval = s.replace(/"/g, "'") //  " sollte EXCELESCCHAR sein ist aber umständlich
				if (retval.match(/\n/)) {retval = EXCELESCCHAR + retval + EXCELESCCHAR}
				return retval
			}
			function printline(fw, line) {
//				for (zi = 0; zi < line.length; zi++) {
//					field = line[zi]
				forEach(line,
					function print1ine(field,idx){
						if (idx > 0) {
							fw.write(EXCELCSVSEP)
						}
						try {
							if (typeof field == 'string') {
								fw.write(escapeexcelchars(field) )
							} else if (field.length == 0) {
								fw.write('') // empty List
							} else if (field.length == 1) {
								fw.write(escapeexcelchars(field[0])) // single string in List
							} else {
								// list of Strings
								fw.write(escapeexcelchars(field.join(EXCELMULTILINESEP)) )
							}
						} catch (err) {linemessage(typeof field, field,line); throw err}
					}
				)				
				fw.write(EXCELLINEEND)
			}

			function printlines(fw, entry) {
				for (ie = 0; ie < entry.length; ie++) {
					line = entry[ie]
						// es ist eine Liste von Zeilen
					printline(fw, line)
				}
			}

			function json2csv(fw, allMapping) {
				fw.write(EXCELBOM)
				for (key in allMapping) {
					entry = allMapping[key]
					switch (key) {
						case "model":
						case "header":
						case "subheader":
							fw.write(entry.join(EXCELCSVSEP))
							fw.write(EXCELLINEEND)
							break;
						case "attrlist":
							printlines(fw, entry)
							break;
						case "footer":
							fw.write(entry)
							fw.write(EXCELLINEEND)
							break;
						default:
							fw.write('unbekannter Eintrag ' + key)
					}
				}
			}

			function gatherModel() {
				g_logicalModel = model.getDesign().getLogicalDesign();
				g_entitySet = g_logicalModel.getEntitySet()
				g_relationSet = g_logicalModel.getRelationSet()
				g_inheritanceSet = g_logicalModel.getInheritanceRelationSet()
				g_rmodels = model.getDesign().getRelationalDesigns().toArray();
			}

			function printjson(fw, format, allmapping) {
				switch (format) {
					case FORMATJSON:
						fw.write(JSON.stringify(allmapping, null, 2)); // spacing level = 2)
						break;
					case FORMATCSV:
						json2csv(fw, allmapping)
						break;
					default:
						throw new Error("invalid format " + format)
				}
			}

			function printMatrix(fw, nurX, format) {
				gatherModel()

				getAllMappings(g_rmodels)

				if (nurX) {
					allmapping = {
						"header": ['entity', 'attr']
					}
					for (ih = 0; ih < g_rmodels.length; ih++) {
						//throw new Error("\nrmodel: " + g_rmodels[ih].getName() + '|'+g_rmodels[ih] + "\n");
						allmapping["header"].push(g_rmodels[ih].getName())
					}
				} else {
					allmapping = {
						"header": ['Information model', ''],
						"subheader": ['entity', 'attr']
					}
					for (ih = 0; ih < g_rmodels.length; ih++) {
						allmapping["header"].push(g_rmodels[ih].getName(), '', '')
						allmapping["subheader"].push('table', 'column', 'ID')
					}
				}

				//throw new Error("\nheaders: " + allmapping["header"] + "\n");
				allmapping["attrlist"] = mappings2json(g_rmodels, g_entitySet.toArray(), nurX)
				allmapping["attrlist"] = allmapping["attrlist"].concat(mappings2json(g_rmodels, g_relationSet.toArray(), nurX))

				allmapping["footer"] = 'created by ODM, ' + curDateStr();
				printjson(fw, format, allmapping)
			}

			function printCVS(fw, format,relModel) {

				// lies alle Mappings des gewählten Modells
				getAllMappings([relModel])
				allmapping = {
					"model": [relModel.getName(), '', 'Information model', ''],
					"header": ['tableName', 'columnName','entityName', 'attrName'],
					"attrlist": gatherCols(relModel)
				}
				printjson(fw, format, allmapping)
			}

			function printDevCVS(fw, format,relModel) {
				// lies alle Mappings des gewählten Modells
				mymodelname = relModel.getName()
				allmapping = {
					"model": [mymodelname,'','','','','','', 'Information model',''],
					"header": ['tableName', 'columnName','datatype','mand.','def. value','descr','rules','entity','attribute'],
					"attrlist": gatherDevCols(relModel)
				}
				// Add all relational models except myself to the header
				for (ih = 0; ih < g_rmodels.length; ih++) {
					if (g_rmodels[ih].getName() != mymodelname) {
						//linemessage(ih,g_rmodels[ih].getName(), mymodelname)
						allmapping["model"].push(g_rmodels[ih].getName(), '', '')
						allmapping["header"].push('table','column','ID')
					}
				}

				printjson(fw, format, allmapping)
			}

			function chooseoutputfilename(pfilename, pformat) {
				fileName = chooseFile(g_exportDirec, pfilename +
					((pformat == FORMATJSON) ?'.js' : ((pformat == FORMATCSV) ?'.csv' :'txt')))
				return fileName
			}

			function outputformat() {
				var formatauswahl = [FORMATJSON, FORMATCSV]
				antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null,
					"Output format",
					"choose output format",
					QUESTIONMESSAGE,
					null,
					formatauswahl, FORMATCSV);
				return antwort
			}

			function print1Mapping() {
				gatherModel()
				var relModel = chooseModel();
				if (relModel == null) return;

				format = outputformat()
				if (format == null) {
					return 
				}
				filename = chooseoutputfilename(relModel.getName(), format)
				if (filename == null) {
					return 
				} else {
					fw = createFile(filename)
				}
				printCVS(fw, format,relModel)
				fw.close();
				message("Mapping file " + fileName + " for model " + relModel.getName() + " created.");
			}

			function printDevMapping() {
				gatherModel()
				var relModel = chooseModel();
				if (relModel == null) return;

				format = outputformat()
				if (format == null) {
					return null
				}
				filename = chooseoutputfilename(relModel.getName()+'_dev', format)
				if (filename == null) {
					return
				} else {
					fw = createFile(filename)
				}
				getAllMappings(g_rmodels)
				printDevCVS(fw, format,relModel)
				fw.close();
				message("Mapping file " + fileName + " for model " + relModel.getName() + " created.");
			}


			function printAllMapping(nurX) {
				format = outputformat()
				if (format == null) {
					return null
				}
				filename = model.getDesign().getName()
				filename = chooseoutputfilename(filename + (nurX ? 'X' : ''), format)
				if (filename == null) {
					return
				} else {
					fw = createFile(filename)
				}
				printMatrix(fw, nurX, format)
				fw.close();
				message("Mapping file " + fileName + " created.");
			}

			function printXMapping() {
				printAllMapping(true)
			}

			function printNameMapping() {
				printAllMapping(false)
			}

			// Autoren: aro, stb
// Functions:
// createsubview - creates a new subview (according to entered zoomlevel) based on the current subview + executes "showhideelements" at the end
// showhideelements - logs all visibility errors according to defined zoomlevel and displayed parentsubview
// initzoomlevel - set only "not set" zoomlevel definitions according standardrules

//InitVars begin
var CODEVERSION = '0.2'
var PLAINMESSAGE = 1
var ERRORMESSAGE = 0
var WARNINGMESSAGE = 2
var QUESTIONMESSAGE = 3

var g_minzoomlevel = 0
var g_maxzoomlevel = 4
var g_logger = model.getAppView()
//InitVars end

//HelperFunctions start
function fullmessage(msg,type) {
    Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg,'ODM-Message', type)
}

function promptmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showInputDialog(null, msg,'ODM-Promtbox', type)
    return retval
}

function confirmmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showConfirmDialog(null, msg,'ODM-Confirmbox', type)
    if (retval == 0) {
        return true
    }else{
        return false
    }
}

function error(msg) {
    fullmessage(msg,ERRORMESSAGE)
}

function message(msg) {
    fullmessage(msg,PLAINMESSAGE)
}

function prompt(msg){
    var retval = promptmessage(msg,QUESTIONMESSAGE)
    return retval
}

function confirm(msg){
    var retval = confirmmessage(msg,0)
    return retval
}

function isNumeric(n) {
    return !isNaN(parseFloat(n)) && isFinite(n)
}
//HelperFunctions end

//LogicalFunctions start
function getsubview(thissv){
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    var retval = null
    for (var vv=0;vv<svlist.length;vv++){
        var checksv = svlist[vv]
        if (((thissv == null) && (checksv.isCurrentDPV())) || (thissv == checksv)) {
            retval = checksv
            break
        }
    }
    return retval
}

function getcommentvalue(srcobj,srcvalue){      
    var retval = null
    var commentlines = []
    commentlines = srcobj.getComment().split("\n")
    for (var vv=0;vv<commentlines.length;vv++){
        if (commentlines[vv].contains(srcvalue+"=")){
            retval = commentlines[vv].replace(srcvalue+"=","").trim()
            break
        }
    }
    if (((retval == null) || (retval == "")) && (srcvalue == "zoomlevel")) {
        retval = g_minzoomlevel
        message("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
        g_logger.logMessage("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
    }
    return retval
}

function getzoomlevelprompt(){
    var retval = prompt('Choose desired zoomlevel')
    if ((!(isNumeric(retval))) || (retval > g_maxzoomlevel) || (retval < g_minzoomlevel)) {
        error("ERROR: No correct zoomlevel entered")
        g_logger.logMessage("ERROR: No correct zoomlevel entered")
        retval = null
    }
    return retval
}

function getMinMax(checkObj){
    g_minzl = checkObj.getProperty("minzoomlevel")  
    g_maxzl = checkObj.getProperty("maxzoomlevel")
    if ((!(isNumeric(g_minzl))) || (g_minzl < g_minzoomlevel)){
        g_minzl = g_minzoomlevel
        g_logger.logMessage("No correct zoomlevel (min) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }
    if ((!(isNumeric(g_maxzl))) || (g_maxzl > g_maxzoomlevel)){
        g_maxzl = g_maxzoomlevel
        g_logger.logMessage("No correct zoomlevel (max) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }    
}
function checkSetDescAttr(checkObj){
    var thisdescflag = checkObj.getProperty("isdescriptive")
    if (thisdescflag == ""){
        thisdescflag = "FALSE"
        var keys = checkObj.getEntity().getUniqueIdentifiers()
        for (var ik=0;ik<keys.length;ik++){
            key = keys[ik]
            var attrkeys = key.getElementsCollection()
            for (var ik2=0;ik2<attrkeys.length;ik2++){
                var attrkey = attrkeys[ik2]
                if (attrkey == checkObj){
                    thisdescflag = "TRUE"
                    break
                }
            }
        }            
        checkObj.setProperty("isdescriptive", thisdescflag)
    }
}

function calcnewMinMax(checkObj){
    //DEV
    checkObj.setProperty("minzoomlevel","")  
    checkObj.setProperty("maxzoomlevel","")  
    checkObj.setProperty("isdescriptive","")  
    //DEV

    var minzl = checkObj.getProperty("minzoomlevel")  
    var maxzl = checkObj.getProperty("maxzoomlevel")  
    var newminzl = g_minzoomlevel
    var newmaxzl = g_maxzoomlevel
    switch(checkObj.getObjectTypeName().toString()){
        case "Entity":
            var attrs = checkObj.getAttributes().toArray()
            var relas = checkObj.getRelations().toArray()
            //DEV Not Root?
            var haschildren = false
            for (var ir=0;ir<relas.length;ir++){
                var rela = relas[ir]
                if (rela.getSourceEntity() == checkObj){
                    haschildren = true
                    break
                }
            }
            if ((attrs.length == 0) && (!(haschildren))){
                newmaxzl = 1
            }else if((attrs.length > 0) && (!(haschildren))){
                var hasdescattr = false
                for (var ia=0;ia<attrs.length;ia++){
                    var attr = attrs[ia]
                    checkSetDescAttr(attr)
                    if (attr.getProperty("isdescriptive") == "TRUE"){
                        hasdescattr = true
                    }
                }
                if (!(hasdescattr)){
                    newmaxzl = 2
                }
            }
            break
        case "Attribute":
            checkSetDescAttr(checkObj)
            var thisdescflag = checkObj.getProperty("isdescriptive")
            if (thisdescflag == "FALSE") {
                newmaxzl = 0
            }else{
                newmaxzl = 2
            }
            break
    }
    g_logger.logMessage("DEV: Set \""+checkObj+"\" ("+checkObj.getObjectTypeName()+") min/max to: "+newminzl+"/"+newmaxzl)
    if (!(isNumeric(minzl))){
        //DEV
        //checkObj.setProperty("minzoomlevel",newminzl)      
    }
    if ((!(isNumeric(maxzl))) || ((maxzl == g_maxzoomlevel) && (maxzl != newmaxzl))) {
        //DEV
        //checkObj.setProperty("maxzoomlevel",newmaxzl)
    }
}

function addChildrenToList(svObj, entityList, entityObj, checkzl){  
    var entityChildren = entityObj.getHierarchicalChildren()
    for (var ic=0;ic<entityChildren.length;ic++){
        var entityChild = entityChildren[ic]
        getMinMax(entityChild)
        if (!((checkzl > g_maxzl) || (checkzl < g_minzl))){    
            var thistv0 = entityChild.getFirstViewForDPV(svObj)
            if (thistv0 != null){
                var thiscell0 = thistv0.getCellView().getCell()
                entityList.push(thiscell0)
                if (entityChild.getHierarchicalChildrenCount() > 0) {
                    entityList = addChildrenToList(svObj, entityList, entityChild, checkzl)
                }
            }
        }
    }
    return entityList
}
//LogicalFunctions end

//createsubview start
function createsubview(){
    var sv = getsubview(null)
    var newzlevel = getzoomlevelprompt()
    if ((sv == null) || (newzlevel == null)){
        return
    }
    var sventities = sv.getTVShapes()
    var list = []
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function createsubview")

    //Mark all hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalRoot() == true)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){               
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Mark all non-hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalEntityType() == false)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){       
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Create new subview & cleanup (rename, set comment, show elements, hide attributes)
    sv.getWorkSpace().setSelectionCells(list)
    sv.createSubViewFromSelected()
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    for (var vv=0;vv<svlist.length;vv++){
        var newsv = svlist[vv]
        if (newsv.isCurrentDPV()) {            
            newsv.setName(sv+"_ZL"+newzlevel)
            newsv.setComment("zoomlevel="+newzlevel+"\nparentview="+sv)
            newsv.setShowLegend(sv.showLegend())
            newsv.setShowLabels(sv.showLabels())
            newsv.setShowRelAttributes(sv.showRelAttributes())
            newsv.setShowGrid(sv.showGrid())
            newsv.setShowPageGrid(sv.showPageGrid())
            var newsventities = newsv.getTVShapes()
            for (var ie=0;ie<newsventities.length;ie++){
                var newsventity = newsventities[ie]
                var newentity = model.getEntitySet().getByName(newsventity)
                if (newentity != null) {
                    if (newentity.getName() == newsventity){          
                        var attrs = newentity.getAttributes().toArray()
                        for (var ia=0;ia<attrs.length;ia++) {
                            var attr = attrs[ia]
                            getMinMax(attr)
                            var hiddenElements = newsventity.getHiddenElements()
                            var isOnSVEntity = true
                            for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                                var hiddenElement = hiddenElements[ia2]
                                if (attr == hiddenElement){
                                    isOnSVEntity = false
                                }
                            }
                            if (((newzlevel > g_maxzl) || (newzlevel < g_minzl)) && (isOnSVEntity)){
                                if (!(newsventity.isHideElementsInCurrentOnly())){
                                    newsventity.setHideElementsInCurrentOnly(true)
                                }
                                hiddenElements.add(attr)
                            }
                        }
                    }
                }
            }
        }
    }
    g_logger.logMessage("End function createsubview")
    showhideelements()    
}
//createsubview start

//showhideelements start
function showhideelements(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function showhideelements")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    var sv = getsubview(null)
    var sventities = sv.getTVShapes()
    var svrelations = sv.getTVConnectors()
    var svzlevel = getcommentvalue(sv,"zoomlevel")
    var svpview = getcommentvalue(sv,"parentview")
    var haspv = false
    if ((svpview != null) && (svpview != "")){
        haspv = true
        var pv = getsubview(svpview)
        var pvzlevel = getcommentvalue(pv,"zoomlevel")
        var pventities = pv.getTVShapes()
        var pvrelations = pv.getTVConnectors()    
    }
    var NoOfDifZL = 0
    var NoOfDifPV = 0
    var logPrefix = ""

    //Zoomlevelcheck entity begin
    logPrefix = "ZoomLevelCheck > Entity"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    var showAttributes = []
    var hideAttributes = []    
    for (var ie = 0; ie < entities.length; ie++){
        var entity = entities[ie]
        var isOnSV = false
        for (var ie2=0;ie2<sventities.length;ie2++){
            var sventity = sventities[ie2]
            if (entity.getName() == sventity){
                isOnSV = true               
                var attrs = entity.getAttributes().toArray()
                for (var ia=0;ia<attrs.length;ia++) {
                    var attr = attrs[ia]
                    getMinMax(attr)
                    var isOnSVEntity = true
                    var hiddenElements = sventity.getHiddenElements()
                    for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                        var hiddenElement = hiddenElements[ia2]
                        if (attr == hiddenElement){
                            isOnSVEntity = false
                            break
                        }
                    }
                    if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)) {
                        if (isOnSVEntity) {
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+attr)
                            NoOfDifZL++
                        }
                    }else{
                        if (!(isOnSVEntity)){
                            showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)    
                            NoOfDifZL++
                        }
                    }
                }    
                break                         
            }
        }
        getMinMax(entity)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+entity)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+entity)
                NoOfDifZL++
            }
        }
    }
    for (var i=0;i<showElements.length;i++){
        g_logger.logMessage(showElements[i])
    }
    for (var i=0;i<hideElements.length;i++){
        g_logger.logMessage(hideElements[i])
    }
    for (var i=0;i<showAttributes.length;i++){
        g_logger.logMessage(showAttributes[i])
    }
    for (var i=0;i<hideAttributes.length;i++){
        g_logger.logMessage(hideAttributes[i])
    }
    //Zoomlevelcheck entity end

    //Zoomlevelcheck relation begin
    logPrefix = "ZoomLevelCheck > Relation"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    for (var ir = 0; ir < relations.length; ir++){
        var relation = relations[ir]
        var isOnSV = false
        for (var ir2=0;ir2<svrelations.length;ir2++){
            var svrelation = svrelations[ir2]
            if (relation.getName() == svrelation){
                isOnSV = true
                break
            }
        }
        getMinMax(relation)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+relation)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+relation)
                NoOfDifZL++
            }
        }
    }   
    for (var is=0;is<showElements.length;is++){
        g_logger.logMessage(showElements[is])
    }
    for (var ih=0;ih<hideElements.length;ih++){
        g_logger.logMessage(hideElements[ih])
    }
    //Zoomlevelcheck relation end

    //Parentviewcompare entity begin
    if (haspv){
        logPrefix = "ParentViewCompare > Entity"
        g_logger.logMessage(logPrefix)
        var showAttributes = []
        var hideAttributes = []
        for (var ie = 0; ie < pventities.length; ie++){
            var pventity = pventities[ie]
            var entity = model.getEntitySet().getByName(pventity)
            var thissventity = null
            var isOnSV = false
            for (var ie2=0;ie2<sventities.length;ie2++){
                var sventity = sventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnSV = true
                    thissventity = sventity
                    break
                }
            }
            if (!(isOnSV)){            
                if (entity != null){
                    getMinMax(entity)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+entity)
                        NoOfDifPV++
                    }
                }
            }else{
                var pvhiddenElements = pventity.getHiddenElements()
                var svhiddenElements = thissventity.getHiddenElements()
                for (var ih=0;ih<pvhiddenElements.length;ih++){
                    var pvhiddenElement = pvhiddenElements[ih]
                    getMinMax(pvhiddenElement)
                    if (!((pvzlevel > g_maxzl) || (pvzlevel < g_minzl))) {
                        for (var ih2=0;ih2<svhiddenElements.length;ih2++){
                            if (pvhiddenElements[ih] == svhiddenElements[ih2]){
                                isOnSV = false
                                break
                            }
                        }
                        if (isOnSV){
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+pvhiddenElements[ih])
                            NoOfDifPV++
                        } 
                    }
                }
                if (entity != null){
                    var attrs = entity.getAttributes().toArray()
                    for (var ia=0;ia<attrs.length;ia++) {
                        var attr = attrs[ia]
                        getMinMax(attr)
                        var isOnPV = true
                        if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)) {
                            for (var ih=0;ih<pvhiddenElements.length;ih++){
                                if (pvhiddenElements[ih] == attr){
                                    isOnPV = false
                                    break
                                }
                            }
                            if (isOnPV){
                                isOnSV = true
                                for (var ih=0;ih<svhiddenElements.length;ih++){
                                    if (svhiddenElements[ih] == attr){
                                        isOnSV = false
                                        break
                                    }
                                }
                                if (!(isOnSV)){
                                    showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)
                                    NoOfDifPV++
                                }
                            }
                        }
                    }        
                }
            }
        }
        for (var ie = 0; ie < sventities.length; ie++){
            var sventity = sventities[ie]
            var isOnPV = false
            for (var ie2=0;ie2<pventities.length;ie2++){
                var pventity = pventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+sventity) 
                NoOfDifPV++
            }
        }
        for (var i=0;i<showAttributes.length;i++){
            g_logger.logMessage(showAttributes[i])
        }
        for (var i=0;i<hideAttributes.length;i++){
            g_logger.logMessage(hideAttributes[i])
        }
        //Parentviewcompare entity end

        //Parentviewcompare relation begin
        logPrefix = "ParentViewCompare > Relation"
        g_logger.logMessage(logPrefix)
        for (var ir = 0; ir < pvrelations.length; ir++){
            var pvrelation = pvrelations[ir]
            var isOnSV = false
            for (var ir2=0;ir2<svrelations.length;ir2++){
                var svrelation = svrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnSV = true
                    break
                }
            }
            if (!(isOnSV)){
                var relation = model.getRelationSet().getByName(pvrelation)
                if (relation != null){
                    getMinMax(relation)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+pvrelation)
                        NoOfDifPV++
                    }
                }
            }
        }
        for (var ir = 0; ir < svrelations.length; ir++){
            var svrelation = svrelations[ir]
            var isOnPV = false
            for (var ir2=0;ir2<pvrelations.length;ir2++){
                var pvrelation = pvrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+svrelation)
                NoOfDifPV++
            }
        }
    }else{
        g_logger.logMessage("CHECK: No comparison of the parent view due to missing ABC definition")
    }
    //Parentviewcompare relation end   
    var finalmessage = "Showhideelements result:"
    if (NoOfDifZL > 0){
        finalmessage += "\n"+NoOfDifZL+" differences to zoomlevel definition found!"
    }
    if (NoOfDifPV > 0){
        finalmessage += "\n"+NoOfDifPV+" differences to parentview definition found!"
    }
    if ((NoOfDifPV == 0) && (NoOfDifZL == 0)){
        finalmessage += "\nNo differences found."
    }else{
        finalmessage += "\nPlease check log-messages."
    }
    message(finalmessage)
    g_logger.logMessage("End function showhideelements")       
} 
//showhideelements end

//initzoomlevel start
function initzoomlevel(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function initzoomlevel")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    //setMinMax to entities
    for (var ie=0;ie<entities.length;ie++){
        var entity = entities[ie]
        calcnewMinMax(entity)
        //setMinMax to attributes of entity
        var attrs = entity.getAttributes().toArray()
        for (var ia=0;ia<attrs.length;ia++) {
            var attr = attrs[ia]
            calcnewMinMax(attr)
        }
    }
    /*
    //setMinMax to relations
    for (var ir=0;ir<relations.length;ir++){
        var relation = relations[ir]
        calcnewMinMax(relation)
    }
    */
    g_logger.logMessage("End function initzoomlevel")
}
//initzoomlevel end

			// Autoren: aro, stb
// Functions:
// createsubview - creates a new subview (according to entered zoomlevel) based on the current subview + executes "showhideelements" at the end
// showhideelements - logs all visibility errors according to defined zoomlevel and displayed parentsubview
// initzoomlevel - set only "not set" zoomlevel definitions according standardrules

//InitVars begin
var CODEVERSION = '0.2'
var PLAINMESSAGE = 1
var ERRORMESSAGE = 0
var WARNINGMESSAGE = 2
var QUESTIONMESSAGE = 3

var g_minzoomlevel = 0
var g_maxzoomlevel = 4
var g_logger = model.getAppView()
//InitVars end

//HelperFunctions start
function fullmessage(msg,type) {
    Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg,'ODM-Message', type)
}

function promptmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showInputDialog(null, msg,'ODM-Promtbox', type)
    return retval
}

function confirmmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showConfirmDialog(null, msg,'ODM-Confirmbox', type)
    if (retval == 0) {
        return true
    }else{
        return false
    }
}

function error(msg) {
    fullmessage(msg,ERRORMESSAGE)
}

function message(msg) {
    fullmessage(msg,PLAINMESSAGE)
}

function prompt(msg){
    var retval = promptmessage(msg,QUESTIONMESSAGE)
    return retval
}

function confirm(msg){
    var retval = confirmmessage(msg,0)
    return retval
}

function isNumeric(n) {
    return !isNaN(parseFloat(n)) && isFinite(n)
}
//HelperFunctions end

//LogicalFunctions start
function getsubview(thissv){
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    var retval = null
    for (var vv=0;vv<svlist.length;vv++){
        var checksv = svlist[vv]
        if (((thissv == null) && (checksv.isCurrentDPV())) || (thissv == checksv)) {
            retval = checksv
            break
        }
    }
    return retval
}

function getcommentvalue(srcobj,srcvalue){      
    var retval = null
    var commentlines = []
    commentlines = srcobj.getComment().split("\n")
    for (var vv=0;vv<commentlines.length;vv++){
        if (commentlines[vv].contains(srcvalue+"=")){
            retval = commentlines[vv].replace(srcvalue+"=","").trim()
            break
        }
    }
    if (((retval == null) || (retval == "")) && (srcvalue == "zoomlevel")) {
        retval = g_minzoomlevel
        message("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
        g_logger.logMessage("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
    }
    return retval
}

function getzoomlevelprompt(){
    var retval = prompt('Choose desired zoomlevel')
    if ((!(isNumeric(retval))) || (retval > g_maxzoomlevel) || (retval < g_minzoomlevel)) {
        error("ERROR: No correct zoomlevel entered")
        g_logger.logMessage("ERROR: No correct zoomlevel entered")
        retval = null
    }
    return retval
}

function getMinMax(checkObj){
    g_minzl = checkObj.getProperty("minzoomlevel")  
    g_maxzl = checkObj.getProperty("maxzoomlevel")
    if ((!(isNumeric(g_minzl))) || (g_minzl < g_minzoomlevel)){
        g_minzl = g_minzoomlevel
        g_logger.logMessage("No correct zoomlevel (min) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }
    if ((!(isNumeric(g_maxzl))) || (g_maxzl > g_maxzoomlevel)){
        g_maxzl = g_maxzoomlevel
        g_logger.logMessage("No correct zoomlevel (max) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }    
}
function checkSetDescAttr(checkObj){
    var thisdescflag = checkObj.getProperty("isdescriptive")
    if (thisdescflag == ""){
        thisdescflag = "FALSE"
        var keys = checkObj.getEntity().getUniqueIdentifiers()
        for (var ik=0;ik<keys.length;ik++){
            key = keys[ik]
            var attrkeys = key.getElementsCollection()
            for (var ik2=0;ik2<attrkeys.length;ik2++){
                var attrkey = attrkeys[ik2]
                if (attrkey == checkObj){
                    thisdescflag = "TRUE"
                    break
                }
            }
        }            
        checkObj.setProperty("isdescriptive", thisdescflag)
    }
}

function calcnewMinMax(checkObj){
    //DEV
    checkObj.setProperty("minzoomlevel","")  
    checkObj.setProperty("maxzoomlevel","")  
    checkObj.setProperty("isdescriptive","")  
    //DEV

    var minzl = checkObj.getProperty("minzoomlevel")  
    var maxzl = checkObj.getProperty("maxzoomlevel")  
    var newminzl = g_minzoomlevel
    var newmaxzl = g_maxzoomlevel
    switch(checkObj.getObjectTypeName().toString()){
        case "Entity":
            var attrs = checkObj.getAttributes().toArray()
            var relas = checkObj.getRelations().toArray()
            //DEV Not Root?
            var haschildren = false
            for (var ir=0;ir<relas.length;ir++){
                var rela = relas[ir]
                if (rela.getSourceEntity() == checkObj){
                    haschildren = true
                    break
                }
            }
            if ((attrs.length == 0) && (!(haschildren))){
                newmaxzl = 1
            }else if((attrs.length > 0) && (!(haschildren))){
                var hasdescattr = false
                for (var ia=0;ia<attrs.length;ia++){
                    var attr = attrs[ia]
                    checkSetDescAttr(attr)
                    if (attr.getProperty("isdescriptive") == "TRUE"){
                        hasdescattr = true
                    }
                }
                if (!(hasdescattr)){
                    newmaxzl = 2
                }
            }
            break
        case "Attribute":
            checkSetDescAttr(checkObj)
            var thisdescflag = checkObj.getProperty("isdescriptive")
            if (thisdescflag == "FALSE") {
                newmaxzl = 0
            }else{
                newmaxzl = 2
            }
            break
    }
    g_logger.logMessage("DEV: Set \""+checkObj+"\" ("+checkObj.getObjectTypeName()+") min/max to: "+newminzl+"/"+newmaxzl)
    if (!(isNumeric(minzl))){
        //DEV
        //checkObj.setProperty("minzoomlevel",newminzl)      
    }
    if ((!(isNumeric(maxzl))) || ((maxzl == g_maxzoomlevel) && (maxzl != newmaxzl))) {
        //DEV
        //checkObj.setProperty("maxzoomlevel",newmaxzl)
    }
}

function addChildrenToList(svObj, entityList, entityObj, checkzl){  
    var entityChildren = entityObj.getHierarchicalChildren()
    for (var ic=0;ic<entityChildren.length;ic++){
        var entityChild = entityChildren[ic]
        getMinMax(entityChild)
        if (!((checkzl > g_maxzl) || (checkzl < g_minzl))){    
            var thistv0 = entityChild.getFirstViewForDPV(svObj)
            if (thistv0 != null){
                var thiscell0 = thistv0.getCellView().getCell()
                entityList.push(thiscell0)
                if (entityChild.getHierarchicalChildrenCount() > 0) {
                    entityList = addChildrenToList(svObj, entityList, entityChild, checkzl)
                }
            }
        }
    }
    return entityList
}
//LogicalFunctions end

//createsubview start
function createsubview(){
    var sv = getsubview(null)
    var newzlevel = getzoomlevelprompt()
    if ((sv == null) || (newzlevel == null)){
        return
    }
    var sventities = sv.getTVShapes()
    var list = []
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function createsubview")

    //Mark all hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalRoot() == true)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){               
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Mark all non-hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalEntityType() == false)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){       
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Create new subview & cleanup (rename, set comment, show elements, hide attributes)
    sv.getWorkSpace().setSelectionCells(list)
    sv.createSubViewFromSelected()
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    for (var vv=0;vv<svlist.length;vv++){
        var newsv = svlist[vv]
        if (newsv.isCurrentDPV()) {            
            newsv.setName(sv+"_ZL"+newzlevel)
            newsv.setComment("zoomlevel="+newzlevel+"\nparentview="+sv)
            newsv.setShowLegend(sv.showLegend())
            newsv.setShowLabels(sv.showLabels())
            newsv.setShowRelAttributes(sv.showRelAttributes())
            newsv.setShowGrid(sv.showGrid())
            newsv.setShowPageGrid(sv.showPageGrid())
            var newsventities = newsv.getTVShapes()
            for (var ie=0;ie<newsventities.length;ie++){
                var newsventity = newsventities[ie]
                var newentity = model.getEntitySet().getByName(newsventity)
                if (newentity != null) {
                    if (newentity.getName() == newsventity){          
                        var attrs = newentity.getAttributes().toArray()
                        for (var ia=0;ia<attrs.length;ia++) {
                            var attr = attrs[ia]
                            getMinMax(attr)
                            var hiddenElements = newsventity.getHiddenElements()
                            var isOnSVEntity = true
                            for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                                var hiddenElement = hiddenElements[ia2]
                                if (attr == hiddenElement){
                                    isOnSVEntity = false
                                }
                            }
                            if (((newzlevel > g_maxzl) || (newzlevel < g_minzl)) && (isOnSVEntity)){
                                if (!(newsventity.isHideElementsInCurrentOnly())){
                                    newsventity.setHideElementsInCurrentOnly(true)
                                }
                                hiddenElements.add(attr)
                            }
                        }
                    }
                }
            }
        }
    }
    g_logger.logMessage("End function createsubview")
    showhideelements()    
}
//createsubview start

//showhideelements start
function showhideelements(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function showhideelements")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    var sv = getsubview(null)
    var sventities = sv.getTVShapes()
    var svrelations = sv.getTVConnectors()
    var svzlevel = getcommentvalue(sv,"zoomlevel")
    var svpview = getcommentvalue(sv,"parentview")
    var haspv = false
    if ((svpview != null) && (svpview != "")){
        haspv = true
        var pv = getsubview(svpview)
        var pvzlevel = getcommentvalue(pv,"zoomlevel")
        var pventities = pv.getTVShapes()
        var pvrelations = pv.getTVConnectors()    
    }
    var NoOfDifZL = 0
    var NoOfDifPV = 0
    var logPrefix = ""

    //Zoomlevelcheck entity begin
    logPrefix = "ZoomLevelCheck > Entity"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    var showAttributes = []
    var hideAttributes = []    
    for (var ie = 0; ie < entities.length; ie++){
        var entity = entities[ie]
        var isOnSV = false
        for (var ie2=0;ie2<sventities.length;ie2++){
            var sventity = sventities[ie2]
            if (entity.getName() == sventity){
                isOnSV = true               
                var attrs = entity.getAttributes().toArray()
                for (var ia=0;ia<attrs.length;ia++) {
                    var attr = attrs[ia]
                    getMinMax(attr)
                    var isOnSVEntity = true
                    var hiddenElements = sventity.getHiddenElements()
                    for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                        var hiddenElement = hiddenElements[ia2]
                        if (attr == hiddenElement){
                            isOnSVEntity = false
                            break
                        }
                    }
                    if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)) {
                        if (isOnSVEntity) {
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+attr)
                            NoOfDifZL++
                        }
                    }else{
                        if (!(isOnSVEntity)){
                            showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)    
                            NoOfDifZL++
                        }
                    }
                }    
                break                         
            }
        }
        getMinMax(entity)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+entity)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+entity)
                NoOfDifZL++
            }
        }
    }
    for (var i=0;i<showElements.length;i++){
        g_logger.logMessage(showElements[i])
    }
    for (var i=0;i<hideElements.length;i++){
        g_logger.logMessage(hideElements[i])
    }
    for (var i=0;i<showAttributes.length;i++){
        g_logger.logMessage(showAttributes[i])
    }
    for (var i=0;i<hideAttributes.length;i++){
        g_logger.logMessage(hideAttributes[i])
    }
    //Zoomlevelcheck entity end

    //Zoomlevelcheck relation begin
    logPrefix = "ZoomLevelCheck > Relation"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    for (var ir = 0; ir < relations.length; ir++){
        var relation = relations[ir]
        var isOnSV = false
        for (var ir2=0;ir2<svrelations.length;ir2++){
            var svrelation = svrelations[ir2]
            if (relation.getName() == svrelation){
                isOnSV = true
                break
            }
        }
        getMinMax(relation)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+relation)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+relation)
                NoOfDifZL++
            }
        }
    }   
    for (var is=0;is<showElements.length;is++){
        g_logger.logMessage(showElements[is])
    }
    for (var ih=0;ih<hideElements.length;ih++){
        g_logger.logMessage(hideElements[ih])
    }
    //Zoomlevelcheck relation end

    //Parentviewcompare entity begin
    if (haspv){
        logPrefix = "ParentViewCompare > Entity"
        g_logger.logMessage(logPrefix)
        var showAttributes = []
        var hideAttributes = []
        for (var ie = 0; ie < pventities.length; ie++){
            var pventity = pventities[ie]
            var entity = model.getEntitySet().getByName(pventity)
            var thissventity = null
            var isOnSV = false
            for (var ie2=0;ie2<sventities.length;ie2++){
                var sventity = sventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnSV = true
                    thissventity = sventity
                    break
                }
            }
            if (!(isOnSV)){            
                if (entity != null){
                    getMinMax(entity)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+entity)
                        NoOfDifPV++
                    }
                }
            }else{
                var pvhiddenElements = pventity.getHiddenElements()
                var svhiddenElements = thissventity.getHiddenElements()
                for (var ih=0;ih<pvhiddenElements.length;ih++){
                    var pvhiddenElement = pvhiddenElements[ih]
                    getMinMax(pvhiddenElement)
                    if (!((pvzlevel > g_maxzl) || (pvzlevel < g_minzl))) {
                        for (var ih2=0;ih2<svhiddenElements.length;ih2++){
                            if (pvhiddenElements[ih] == svhiddenElements[ih2]){
                                isOnSV = false
                                break
                            }
                        }
                        if (isOnSV){
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+pvhiddenElements[ih])
                            NoOfDifPV++
                        } 
                    }
                }
                if (entity != null){
                    var attrs = entity.getAttributes().toArray()
                    for (var ia=0;ia<attrs.length;ia++) {
                        var attr = attrs[ia]
                        getMinMax(attr)
                        var isOnPV = true
                        if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)) {
                            for (var ih=0;ih<pvhiddenElements.length;ih++){
                                if (pvhiddenElements[ih] == attr){
                                    isOnPV = false
                                    break
                                }
                            }
                            if (isOnPV){
                                isOnSV = true
                                for (var ih=0;ih<svhiddenElements.length;ih++){
                                    if (svhiddenElements[ih] == attr){
                                        isOnSV = false
                                        break
                                    }
                                }
                                if (!(isOnSV)){
                                    showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)
                                    NoOfDifPV++
                                }
                            }
                        }
                    }        
                }
            }
        }
        for (var ie = 0; ie < sventities.length; ie++){
            var sventity = sventities[ie]
            var isOnPV = false
            for (var ie2=0;ie2<pventities.length;ie2++){
                var pventity = pventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+sventity) 
                NoOfDifPV++
            }
        }
        for (var i=0;i<showAttributes.length;i++){
            g_logger.logMessage(showAttributes[i])
        }
        for (var i=0;i<hideAttributes.length;i++){
            g_logger.logMessage(hideAttributes[i])
        }
        //Parentviewcompare entity end

        //Parentviewcompare relation begin
        logPrefix = "ParentViewCompare > Relation"
        g_logger.logMessage(logPrefix)
        for (var ir = 0; ir < pvrelations.length; ir++){
            var pvrelation = pvrelations[ir]
            var isOnSV = false
            for (var ir2=0;ir2<svrelations.length;ir2++){
                var svrelation = svrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnSV = true
                    break
                }
            }
            if (!(isOnSV)){
                var relation = model.getRelationSet().getByName(pvrelation)
                if (relation != null){
                    getMinMax(relation)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+pvrelation)
                        NoOfDifPV++
                    }
                }
            }
        }
        for (var ir = 0; ir < svrelations.length; ir++){
            var svrelation = svrelations[ir]
            var isOnPV = false
            for (var ir2=0;ir2<pvrelations.length;ir2++){
                var pvrelation = pvrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+svrelation)
                NoOfDifPV++
            }
        }
    }else{
        g_logger.logMessage("CHECK: No comparison of the parent view due to missing ABC definition")
    }
    //Parentviewcompare relation end   
    var finalmessage = "Showhideelements result:"
    if (NoOfDifZL > 0){
        finalmessage += "\n"+NoOfDifZL+" differences to zoomlevel definition found!"
    }
    if (NoOfDifPV > 0){
        finalmessage += "\n"+NoOfDifPV+" differences to parentview definition found!"
    }
    if ((NoOfDifPV == 0) && (NoOfDifZL == 0)){
        finalmessage += "\nNo differences found."
    }else{
        finalmessage += "\nPlease check log-messages."
    }
    message(finalmessage)
    g_logger.logMessage("End function showhideelements")       
} 
//showhideelements end

//initzoomlevel start
function initzoomlevel(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function initzoomlevel")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    //setMinMax to entities
    for (var ie=0;ie<entities.length;ie++){
        var entity = entities[ie]
        calcnewMinMax(entity)
        //setMinMax to attributes of entity
        var attrs = entity.getAttributes().toArray()
        for (var ia=0;ia<attrs.length;ia++) {
            var attr = attrs[ia]
            calcnewMinMax(attr)
        }
    }
    /*
    //setMinMax to relations
    for (var ir=0;ir<relations.length;ir++){
        var relation = relations[ir]
        calcnewMinMax(relation)
    }
    */
    g_logger.logMessage("End function initzoomlevel")
}
//initzoomlevel end

			// Autoren: aro, stb
// Functions:
// createsubview - creates a new subview (according to entered zoomlevel) based on the current subview + executes "showhideelements" at the end
// showhideelements - logs all visibility errors according to defined zoomlevel and displayed parentsubview
// initzoomlevel - set only "not set" zoomlevel definitions according standardrules

//InitVars begin
var CODEVERSION = '0.2'
var PLAINMESSAGE = 1
var ERRORMESSAGE = 0
var WARNINGMESSAGE = 2
var QUESTIONMESSAGE = 3

var g_minzoomlevel = 0
var g_maxzoomlevel = 4
var g_logger = model.getAppView()
//InitVars end

//HelperFunctions start
function fullmessage(msg,type) {
    Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg,'ODM-Message', type)
}

function promptmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showInputDialog(null, msg,'ODM-Promtbox', type)
    return retval
}

function confirmmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showConfirmDialog(null, msg,'ODM-Confirmbox', type)
    if (retval == 0) {
        return true
    }else{
        return false
    }
}

function error(msg) {
    fullmessage(msg,ERRORMESSAGE)
}

function message(msg) {
    fullmessage(msg,PLAINMESSAGE)
}

function prompt(msg){
    var retval = promptmessage(msg,QUESTIONMESSAGE)
    return retval
}

function confirm(msg){
    var retval = confirmmessage(msg,0)
    return retval
}

function isNumeric(n) {
    return !isNaN(parseFloat(n)) && isFinite(n)
}
//HelperFunctions end

//LogicalFunctions start
function getsubview(thissv){
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    var retval = null
    for (var vv=0;vv<svlist.length;vv++){
        var checksv = svlist[vv]
        if (((thissv == null) && (checksv.isCurrentDPV())) || (thissv == checksv)) {
            retval = checksv
            break
        }
    }
    return retval
}

function getcommentvalue(srcobj,srcvalue){      
    var retval = null
    var commentlines = []
    commentlines = srcobj.getComment().split("\n")
    for (var vv=0;vv<commentlines.length;vv++){
        if (commentlines[vv].contains(srcvalue+"=")){
            retval = commentlines[vv].replace(srcvalue+"=","").trim()
            break
        }
    }
    if (((retval == null) || (retval == "")) && (srcvalue == "zoomlevel")) {
        retval = g_minzoomlevel
        message("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
        g_logger.logMessage("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
    }
    return retval
}

function getzoomlevelprompt(){
    var retval = prompt('Choose desired zoomlevel')
    if ((!(isNumeric(retval))) || (retval > g_maxzoomlevel) || (retval < g_minzoomlevel)) {
        error("ERROR: No correct zoomlevel entered")
        g_logger.logMessage("ERROR: No correct zoomlevel entered")
        retval = null
    }
    return retval
}

function getMinMax(checkObj){
    g_minzl = checkObj.getProperty("minzoomlevel")  
    g_maxzl = checkObj.getProperty("maxzoomlevel")
    if ((!(isNumeric(g_minzl))) || (g_minzl < g_minzoomlevel)){
        g_minzl = g_minzoomlevel
        g_logger.logMessage("No correct zoomlevel (min) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }
    if ((!(isNumeric(g_maxzl))) || (g_maxzl > g_maxzoomlevel)){
        g_maxzl = g_maxzoomlevel
        g_logger.logMessage("No correct zoomlevel (max) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }    
}
function checkSetDescAttr(checkObj){
    var thisdescflag = checkObj.getProperty("isdescriptive")
    if (thisdescflag == ""){
        thisdescflag = "FALSE"
        var keys = checkObj.getEntity().getUniqueIdentifiers()
        for (var ik=0;ik<keys.length;ik++){
            key = keys[ik]
            var attrkeys = key.getElementsCollection()
            for (var ik2=0;ik2<attrkeys.length;ik2++){
                var attrkey = attrkeys[ik2]
                if (attrkey == checkObj){
                    thisdescflag = "TRUE"
                    break
                }
            }
        }            
        checkObj.setProperty("isdescriptive", thisdescflag)
    }
}

function calcnewMinMax(checkObj){
    //DEV
    checkObj.setProperty("minzoomlevel","")  
    checkObj.setProperty("maxzoomlevel","")  
    checkObj.setProperty("isdescriptive","")  
    //DEV

    var minzl = checkObj.getProperty("minzoomlevel")  
    var maxzl = checkObj.getProperty("maxzoomlevel")  
    var newminzl = g_minzoomlevel
    var newmaxzl = g_maxzoomlevel
    switch(checkObj.getObjectTypeName().toString()){
        case "Entity":
            var attrs = checkObj.getAttributes().toArray()
            var relas = checkObj.getRelations().toArray()
            //DEV Not Root?
            var haschildren = false
            for (var ir=0;ir<relas.length;ir++){
                var rela = relas[ir]
                if (rela.getSourceEntity() == checkObj){
                    haschildren = true
                    break
                }
            }
            if ((attrs.length == 0) && (!(haschildren))){
                newmaxzl = 1
            }else if((attrs.length > 0) && (!(haschildren))){
                var hasdescattr = false
                for (var ia=0;ia<attrs.length;ia++){
                    var attr = attrs[ia]
                    checkSetDescAttr(attr)
                    if (attr.getProperty("isdescriptive") == "TRUE"){
                        hasdescattr = true
                    }
                }
                if (!(hasdescattr)){
                    newmaxzl = 2
                }
            }
            break
        case "Attribute":
            checkSetDescAttr(checkObj)
            var thisdescflag = checkObj.getProperty("isdescriptive")
            if (thisdescflag == "FALSE") {
                newmaxzl = 0
            }else{
                newmaxzl = 2
            }
            break
    }
    g_logger.logMessage("DEV: Set \""+checkObj+"\" ("+checkObj.getObjectTypeName()+") min/max to: "+newminzl+"/"+newmaxzl)
    if (!(isNumeric(minzl))){
        //DEV
        //checkObj.setProperty("minzoomlevel",newminzl)      
    }
    if ((!(isNumeric(maxzl))) || ((maxzl == g_maxzoomlevel) && (maxzl != newmaxzl))) {
        //DEV
        //checkObj.setProperty("maxzoomlevel",newmaxzl)
    }
}

function addChildrenToList(svObj, entityList, entityObj, checkzl){  
    var entityChildren = entityObj.getHierarchicalChildren()
    for (var ic=0;ic<entityChildren.length;ic++){
        var entityChild = entityChildren[ic]
        getMinMax(entityChild)
        if (!((checkzl > g_maxzl) || (checkzl < g_minzl))){    
            var thistv0 = entityChild.getFirstViewForDPV(svObj)
            if (thistv0 != null){
                var thiscell0 = thistv0.getCellView().getCell()
                entityList.push(thiscell0)
                if (entityChild.getHierarchicalChildrenCount() > 0) {
                    entityList = addChildrenToList(svObj, entityList, entityChild, checkzl)
                }
            }
        }
    }
    return entityList
}
//LogicalFunctions end

//createsubview start
function createsubview(){
    var sv = getsubview(null)
    var newzlevel = getzoomlevelprompt()
    if ((sv == null) || (newzlevel == null)){
        return
    }
    var sventities = sv.getTVShapes()
    var list = []
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function createsubview")

    //Mark all hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalRoot() == true)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){               
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Mark all non-hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalEntityType() == false)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){       
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Create new subview & cleanup (rename, set comment, show elements, hide attributes)
    sv.getWorkSpace().setSelectionCells(list)
    sv.createSubViewFromSelected()
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    for (var vv=0;vv<svlist.length;vv++){
        var newsv = svlist[vv]
        if (newsv.isCurrentDPV()) {            
            newsv.setName(sv+"_ZL"+newzlevel)
            newsv.setComment("zoomlevel="+newzlevel+"\nparentview="+sv)
            newsv.setShowLegend(sv.showLegend())
            newsv.setShowLabels(sv.showLabels())
            newsv.setShowRelAttributes(sv.showRelAttributes())
            newsv.setShowGrid(sv.showGrid())
            newsv.setShowPageGrid(sv.showPageGrid())
            var newsventities = newsv.getTVShapes()
            for (var ie=0;ie<newsventities.length;ie++){
                var newsventity = newsventities[ie]
                var newentity = model.getEntitySet().getByName(newsventity)
                if (newentity != null) {
                    if (newentity.getName() == newsventity){          
                        var attrs = newentity.getAttributes().toArray()
                        for (var ia=0;ia<attrs.length;ia++) {
                            var attr = attrs[ia]
                            getMinMax(attr)
                            var hiddenElements = newsventity.getHiddenElements()
                            var isOnSVEntity = true
                            for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                                var hiddenElement = hiddenElements[ia2]
                                if (attr == hiddenElement){
                                    isOnSVEntity = false
                                }
                            }
                            if (((newzlevel > g_maxzl) || (newzlevel < g_minzl)) && (isOnSVEntity)){
                                if (!(newsventity.isHideElementsInCurrentOnly())){
                                    newsventity.setHideElementsInCurrentOnly(true)
                                }
                                hiddenElements.add(attr)
                            }
                        }
                    }
                }
            }
        }
    }
    g_logger.logMessage("End function createsubview")
    showhideelements()    
}
//createsubview start

//showhideelements start
function showhideelements(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function showhideelements")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    var sv = getsubview(null)
    var sventities = sv.getTVShapes()
    var svrelations = sv.getTVConnectors()
    var svzlevel = getcommentvalue(sv,"zoomlevel")
    var svpview = getcommentvalue(sv,"parentview")
    var haspv = false
    if ((svpview != null) && (svpview != "")){
        haspv = true
        var pv = getsubview(svpview)
        var pvzlevel = getcommentvalue(pv,"zoomlevel")
        var pventities = pv.getTVShapes()
        var pvrelations = pv.getTVConnectors()    
    }
    var NoOfDifZL = 0
    var NoOfDifPV = 0
    var logPrefix = ""

    //Zoomlevelcheck entity begin
    logPrefix = "ZoomLevelCheck > Entity"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    var showAttributes = []
    var hideAttributes = []    
    for (var ie = 0; ie < entities.length; ie++){
        var entity = entities[ie]
        var isOnSV = false
        for (var ie2=0;ie2<sventities.length;ie2++){
            var sventity = sventities[ie2]
            if (entity.getName() == sventity){
                isOnSV = true               
                var attrs = entity.getAttributes().toArray()
                for (var ia=0;ia<attrs.length;ia++) {
                    var attr = attrs[ia]
                    getMinMax(attr)
                    var isOnSVEntity = true
                    var hiddenElements = sventity.getHiddenElements()
                    for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                        var hiddenElement = hiddenElements[ia2]
                        if (attr == hiddenElement){
                            isOnSVEntity = false
                            break
                        }
                    }
                    if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)) {
                        if (isOnSVEntity) {
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+attr)
                            NoOfDifZL++
                        }
                    }else{
                        if (!(isOnSVEntity)){
                            showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)    
                            NoOfDifZL++
                        }
                    }
                }    
                break                         
            }
        }
        getMinMax(entity)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+entity)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+entity)
                NoOfDifZL++
            }
        }
    }
    for (var i=0;i<showElements.length;i++){
        g_logger.logMessage(showElements[i])
    }
    for (var i=0;i<hideElements.length;i++){
        g_logger.logMessage(hideElements[i])
    }
    for (var i=0;i<showAttributes.length;i++){
        g_logger.logMessage(showAttributes[i])
    }
    for (var i=0;i<hideAttributes.length;i++){
        g_logger.logMessage(hideAttributes[i])
    }
    //Zoomlevelcheck entity end

    //Zoomlevelcheck relation begin
    logPrefix = "ZoomLevelCheck > Relation"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    for (var ir = 0; ir < relations.length; ir++){
        var relation = relations[ir]
        var isOnSV = false
        for (var ir2=0;ir2<svrelations.length;ir2++){
            var svrelation = svrelations[ir2]
            if (relation.getName() == svrelation){
                isOnSV = true
                break
            }
        }
        getMinMax(relation)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+relation)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+relation)
                NoOfDifZL++
            }
        }
    }   
    for (var is=0;is<showElements.length;is++){
        g_logger.logMessage(showElements[is])
    }
    for (var ih=0;ih<hideElements.length;ih++){
        g_logger.logMessage(hideElements[ih])
    }
    //Zoomlevelcheck relation end

    //Parentviewcompare entity begin
    if (haspv){
        logPrefix = "ParentViewCompare > Entity"
        g_logger.logMessage(logPrefix)
        var showAttributes = []
        var hideAttributes = []
        for (var ie = 0; ie < pventities.length; ie++){
            var pventity = pventities[ie]
            var entity = model.getEntitySet().getByName(pventity)
            var thissventity = null
            var isOnSV = false
            for (var ie2=0;ie2<sventities.length;ie2++){
                var sventity = sventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnSV = true
                    thissventity = sventity
                    break
                }
            }
            if (!(isOnSV)){            
                if (entity != null){
                    getMinMax(entity)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+entity)
                        NoOfDifPV++
                    }
                }
            }else{
                var pvhiddenElements = pventity.getHiddenElements()
                var svhiddenElements = thissventity.getHiddenElements()
                for (var ih=0;ih<pvhiddenElements.length;ih++){
                    var pvhiddenElement = pvhiddenElements[ih]
                    getMinMax(pvhiddenElement)
                    if (!((pvzlevel > g_maxzl) || (pvzlevel < g_minzl))) {
                        for (var ih2=0;ih2<svhiddenElements.length;ih2++){
                            if (pvhiddenElements[ih] == svhiddenElements[ih2]){
                                isOnSV = false
                                break
                            }
                        }
                        if (isOnSV){
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+pvhiddenElements[ih])
                            NoOfDifPV++
                        } 
                    }
                }
                if (entity != null){
                    var attrs = entity.getAttributes().toArray()
                    for (var ia=0;ia<attrs.length;ia++) {
                        var attr = attrs[ia]
                        getMinMax(attr)
                        var isOnPV = true
                        if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)) {
                            for (var ih=0;ih<pvhiddenElements.length;ih++){
                                if (pvhiddenElements[ih] == attr){
                                    isOnPV = false
                                    break
                                }
                            }
                            if (isOnPV){
                                isOnSV = true
                                for (var ih=0;ih<svhiddenElements.length;ih++){
                                    if (svhiddenElements[ih] == attr){
                                        isOnSV = false
                                        break
                                    }
                                }
                                if (!(isOnSV)){
                                    showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)
                                    NoOfDifPV++
                                }
                            }
                        }
                    }        
                }
            }
        }
        for (var ie = 0; ie < sventities.length; ie++){
            var sventity = sventities[ie]
            var isOnPV = false
            for (var ie2=0;ie2<pventities.length;ie2++){
                var pventity = pventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+sventity) 
                NoOfDifPV++
            }
        }
        for (var i=0;i<showAttributes.length;i++){
            g_logger.logMessage(showAttributes[i])
        }
        for (var i=0;i<hideAttributes.length;i++){
            g_logger.logMessage(hideAttributes[i])
        }
        //Parentviewcompare entity end

        //Parentviewcompare relation begin
        logPrefix = "ParentViewCompare > Relation"
        g_logger.logMessage(logPrefix)
        for (var ir = 0; ir < pvrelations.length; ir++){
            var pvrelation = pvrelations[ir]
            var isOnSV = false
            for (var ir2=0;ir2<svrelations.length;ir2++){
                var svrelation = svrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnSV = true
                    break
                }
            }
            if (!(isOnSV)){
                var relation = model.getRelationSet().getByName(pvrelation)
                if (relation != null){
                    getMinMax(relation)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+pvrelation)
                        NoOfDifPV++
                    }
                }
            }
        }
        for (var ir = 0; ir < svrelations.length; ir++){
            var svrelation = svrelations[ir]
            var isOnPV = false
            for (var ir2=0;ir2<pvrelations.length;ir2++){
                var pvrelation = pvrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+svrelation)
                NoOfDifPV++
            }
        }
    }else{
        g_logger.logMessage("CHECK: No comparison of the parent view due to missing ABC definition")
    }
    //Parentviewcompare relation end   
    var finalmessage = "Showhideelements result:"
    if (NoOfDifZL > 0){
        finalmessage += "\n"+NoOfDifZL+" differences to zoomlevel definition found!"
    }
    if (NoOfDifPV > 0){
        finalmessage += "\n"+NoOfDifPV+" differences to parentview definition found!"
    }
    if ((NoOfDifPV == 0) && (NoOfDifZL == 0)){
        finalmessage += "\nNo differences found."
    }else{
        finalmessage += "\nPlease check log-messages."
    }
    message(finalmessage)
    g_logger.logMessage("End function showhideelements")       
} 
//showhideelements end

//initzoomlevel start
function initzoomlevel(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function initzoomlevel")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    //setMinMax to entities
    for (var ie=0;ie<entities.length;ie++){
        var entity = entities[ie]
        calcnewMinMax(entity)
        //setMinMax to attributes of entity
        var attrs = entity.getAttributes().toArray()
        for (var ia=0;ia<attrs.length;ia++) {
            var attr = attrs[ia]
            calcnewMinMax(attr)
        }
    }
    /*
    //setMinMax to relations
    for (var ir=0;ir<relations.length;ir++){
        var relation = relations[ir]
        calcnewMinMax(relation)
    }
    */
    g_logger.logMessage("End function initzoomlevel")
}
//initzoomlevel end

