	function selectcurlang(plangs){
		langs = []
		for (p in plangs){langs.push(plangs[p])}
		with (JavaGui) {
			var selected = JOptionPane.showInputDialog(null,
				"Choose your default language to start with","Languages",
				JOptionPane.QUESTION_MESSAGE, 
				null, langs,null);
			if (selected == null) {return null}
			selected = selected.substring(0,2)
			g_logger.logMessage("Default languages chosen: " + selected)
			return selected
		}
	}

	function selectlanguages(plangs){
		with (JavaGui) {
			list = new JList(plangs); //data has type Object[]
			list.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
			JOptionPane.showMessageDialog(null, list, "Choose your languages"
							,JOptionPane.INFORMATION_MESSAGE); 
			selvalues = list.getSelectedValuesList()
			if (selvalues.length == 0) {
				return null
			} else {
				g_logger.logMessage("languages chosen: " + selvalues)
			}
		}
		return selvalues
	}

	function initTranslation() {
		getTranslInfo()
		if (Object.keys(g_Params).length == 0) {
			langs = selectlanguages(availablelanguages)
			if (langs == null) {
				message ("TRANLSATION aborted as no languages were chosen");
				return
			}
			for (var i in langs) {
				if (i == 0) {langstext = langs[i].substr(0,2)}
				else {langstext += ','+langs[i].substr(0,2)}
			}
			setLanguages(langstext)
			curlang = selectcurlang(langs)
			if (curlang == null) {
				message ("TRANLSATION aborted as no current-language was chosen");
				return
			}
			setCurrentLang(curlang)
			setVersion(CODEVERSION)
			setDEEPLAuthKey("")
		} else {
			throw new Error("\n***TRANSLATION ("+getVersion()+") already installed***\n");
		}
		//hier gibt es einen Eintrag für die Translation
		init(false);

		fuellUDP(null);

		setTranslInfo()
		model.design.setDirty(true);
		message ("TRANLSATION installed current-language="+getCurrentLang()
			+ " languages="+getLanguages()+" version="+getVersion());
	}

	function changeLanguage() {
		var antwort
		init(false);
		var options = [];
		var langchangefrom = getCurrentLang()
		forEach(getLangArr(), 				
			function do1lang(lang,idx){
			if (lang != langchangefrom) {
				options.push(getCurrentLang() + '->' + lang)
				}
			}
		)
		if (options.length == 1) {
			antwort = options[0]
		} else {
			antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null, 
	        	"Choose language change",
				"Change language",
				QUESTIONMESSAGE,
				null, 
				options, 
				options[0]);
		}
        if (antwort != null){
			var toLang = antwort.substr(-2)
			//Java.type("javax.swing.JOptionPane").showMessageDialog(null, antwort+'|'+toLang);
			g_changedentries = 0
			g_translatedentries = 0
			//g_logger.logMessage("DEBUG: g_dotranslation="+g_dotranslation + "   tolang="+toLang);
			changeLang(getCurrentLang(),toLang);
			msg = "Model language changed from "+langchangefrom+" to "+toLang+".\n"+
					g_changedentries + " entries marked as changed.\n" +
					g_translatedentries + " entries translated."
			g_logger.logMessage(msg)
			linemessage (msg);
			setLabels(false)
			setLabels(true)
		}
	}

	function upgrade09_to_10() {
		forEach(model.getEntitySet().toArray(),
			function do1ent(ent,idx){
				forEach(getLangArr(),
					function do1lang(lang,idx){
						textToNote(lang+"_ENTI_COMMENT",ent,ent.getProperty(lang+"_ENTI_COMMENT"));

						forEach(ent.getAttributes().toArray(),
							function do1attr(attr,idx){
								textToNote(lang+"_ATTR_COMMENT",attr,attr.getProperty(lang+"_ATTR_COMMENT"));
							}
						)
				 	}
				)
			ent.setDirty(true);
			}
		)
	}
