	function upgrade20_to_21() {
		// empty fields are deleted in all elements
		forEach(model.getEntitySet().toArray(),
			function do1ent(ent,idx){
				forEach(getLangArr(),
					function do1lang(lang,idx){
						entcomm = ent.getComment()
						if (entcomm == "") textToNote(lang+"_ENTI_COMMENT",ent,"");
						entsyn = ent.getSynonym()
						if (entsyn == "") ent.setProperty(lang+"_ENTI_SYNONYM","");
						forEach(ent.getAttributes().toArray(),
							function do1attr(attr,idx){
								attrcomm = attr.getComment()
								if (attrcomm == "") textToNote(lang+"_ATTR_COMMENT",attr,"");
							}
						)
				 	}
				)
			ent.setDirty(true);
			}
		)
		forEach(model.getRelationSet().toArray(), 
			function do1rela(rel,idx){
				forEach(getLangArr(),
					function do1lang(lang,idx){
						relafrom = rel.getNameOnSource()
						if (relafrom == "") rel.setProperty(lang+"_RELA_TEXT_FROM","");
						relato = rel.getNameOnTarget()
						if (relato == "") rel.setProperty(lang+"_RELA_TEXT_TO","");
					}
				)
			}
		)
	}

	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (getVersion()  == CODEVERSION) {
			message("TRANSLATE: latest version ("+getVersion()+") is installed")
		} else {
			var upgraded = false
			if (getVersion() == "0.9") {
				upgrade09_to_10();
				upgraded = true
			}
			if (getVersion() == "1.0") {
				upgrade10_to_11();
				upgraded = true
			}
			if (getVersion() == "1.1") {
				upgrade11_to_12();
				upgraded = true
			}
			if (getVersion() == "1.2") {
				upgrade12_to_13();
				upgraded = true
			}
			if (getVersion() == "1.3") {
				upgrade13_to_14();
				upgraded = true
			}
			if (getVersion() == "1.4") {
				upgrade14_to_15();
				upgraded = true
			}
			if (getVersion() == "1.5") {
				upgrade15_to_20();
				upgraded = true
			}
			if (getVersion() == "2.0") {
				upgrade20_to_21();
				upgraded = true
			}
			if (upgraded) {
				setVersion(CODEVERSION)
				setTranslInfo();	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+getVersion()+").\n"
					+"Please contact support\n");
			}
		}			
	}

