			forEach(lparam.split("\n"), 
			     function vals(line,idx){
					 var vals=line.split("=")
					 	if (vals[0] != null && vals[0] != "") {  
							g_Params[vals[0]] = trim(vals[1])
						}
				 }
			 )
		}
	}	

	function param2comment(){
		var deeplkey
		var retval = "TRANSLATION{\n"+CURRENTLANG+"="+getCurrentLang()
						+"\n"+LANGUAGES+"="+getLanguages()
						+"\n"+LASTSYNC+"="+getLastSync()
						+"\n"+VERSION+"="+getVersion()
		deeplkey = getDEEPLAuthKey()			
		if (deeplkey != null) {retval += "\n"+DEEPLAUTHKEY+"="+deeplkey}
		retval += "\n}"
	 	return retval
	}

	function setTranslInfo() {
		var lparam
		setLastSync(curDateStr())
		curComment = model.design.getComment();
		lparam= curComment.match(g_TranslInforegexp);
		if (lparam == null) {model.design.setComment(curComment + param2comment())}
		else {model.design.setComment(
			curComment.replace(g_TranslInforegexp,param2comment()));
		}
	}

	function buildRegExpTag(innertag,tag){
		return tag.replace('<tag>',innertag).replace(/\[/g,'\\[').replace(/\]/g,'\\]')
	}

	function trim(str){
		return str.replace(/^[\s]+|[\s]+$/g,'');
	}

	function textFromNote(tag,obj) {
    	var note = obj.getNotes()
    	var restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	var reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	var re = new RegExp(restart + '([^]*)' + reend)
    	var ma = note.match(re)
    	var retval = ''
	   	if (ma != null) {
			//linemessage("|"+reend+"|\n"+"|"+ma[0]+"|")
	   		retval = trim(ma[1])
		}
		return retval
	}

	function textToNote(tag,obj,value) {
    	var note = obj.getNotes()
    	var restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	var reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	var re = new RegExp(restart + '([^]*)' + reend)
    	var ma = note.match(re)
		var newentry = NOTESSTARTTAG.replace('<tag>',tag)+'\n' 
			+ value 
			+'\n' + NOTESENDTAG.replace('<tag>',tag)
			+'\n'
	   	if (ma == null) {
	   		note = note + newentry
		} else {
			//message("|"+newentry+"|\n"+"|"+ma[0]+"|")
			note = note.replace(ma[0] , newentry)
		}
		obj.setNotes(note)
	}

	function init(istUpgrade){
		getTranslInfo();
		if (Object.keys(g_Params).length == 0) {
			throw new Error("\n***TRANSLATION not installed***\n");
		}
		if (getVersion() != CODEVERSION && !istUpgrade) {
			var msg = "\n***TRANSLATION version mismatch: "
				+"expected " + CODEVERSION + " found "+getVersion()
				+"\nPlease upgrade.***\n"
			throw new Error(msg);
		}
		g_dotranslation = false
		if (getDEEPLAuthKey() != null && getDEEPLAuthKey() != ''){
			g_dotranslation = haveDeeplAccess()
		}
	}

	function logchangedvalue(objname,propname,value,tolang){
		g_logger.logMessage(propname + "-" + objname + ": marked (" + tolang + ") " + value)
	}

	function logtranslation(objname,propname,value,curlang,newvalue,tolang){	
		//g_logger.logMessage("DEBUG: objname="+objname + "   propname="+propname);
		g_logger.logMessage(propname + "-" + objname + ": translated " + value + " (" + curlang + ") to " + newvalue + " (" + tolang + ")")
	}

	//writes the value to the propname in obj for a note (isNote=T) or a field
	function doLangValue(propName,obj,value,isNote,notNull){
		var display, flang, nontranslateprefix, fpropName, fprop, re
		var lpropName = getCurrentLang() + propName;
		var oldval = (isNote) ? textFromNote(lpropName,obj) : obj.getProperty(lpropName);
		var langArr = getLangArr()
		var newvalue = ''

		//DEBUG
		if (((obj.getName() == '') && (propName == ''))
		     || (obj.getName() == '')) {
			message('Obj-Name='+obj.getName()+ '  '+propName);
			display = true;
		} else display = false;

		for (il=0;il<langArr.length;il++) {
			// nur die fremden Sprachen ersetzen
			flang = langArr[il]
			if (flang != getCurrentLang()) {
				// if value contains *xx*, don't add another one
				if (value.match(/^\*[A-Z]{2}\* /)) {
						nontranslateprefix =  ''
					} else {
						nontranslateprefix =  '*'+getCurrentLang()+'* '			
					}
				//markiere oder fülle die fremden Properties
				fpropName = flang + propName;
				fprop = (isNote) ? textFromNote(fpropName,obj) : obj.getProperty(fpropName);
				// Die Reihenfolge der folgenden IF ist wichtig!
				//Falls das Feld leer ist, überschreibe alle Languagefelder mit dem leeren Wert
				if (value == "" && ! notNull) {
					// das original ist leer, leere alle Sprachfelder
					if (isNote) textToNote(fpropName,obj,value);  
						else obj.setProperty(fpropName,value);
				}
				// Falls die Fremdsprache noch automtaisch übersetzt ist ( *XX* vorneweg hat), überschreibe sie
				else if (fprop.match(/^\*[A-Z]{2}\* /)) {
					// nicht übersetzter alter Wert. Falls Translation und
					// der Wert stammt von früherer Nichtübersetung aus der current Lang, 
					// versuchen ihn zu übersetzen. Sonst markiere ihn wieder als nicht übersetzt *XX*
					re = new RegExp("^\\*"+getCurrentLang()+"\\* ");
					if (g_dotranslation && (fprop.match(re))){
						try {newvalue = '**'+translate(getCurrentLang(),flang,value)
							g_translatedentries++
							logtranslation(obj.getName(),propName,value, getCurrentLang(),newvalue ,flang)
							}
						catch (err) {newvalue = nontranslateprefix+value}
					} else {newvalue = nontranslateprefix+value}
					if (isNote) textToNote(fpropName,obj,newvalue);  
						else obj.setProperty(fpropName,newvalue);
				} else if (fprop.startsWith('**')) {
					// ** wurde automatisch übersetzt. Falls Originallang geändert hat, übersetze neu
					if (value != oldval && ! oldval.startsWith('*')) {
						if (g_dotranslation){
							try {newvalue = '**'+translate(getCurrentLang(),flang,value)
								g_translatedentries++
								logtranslation(obj.getName(),propName,value, getCurrentLang(),newvalue ,flang)
							}
								catch (err) {newvalue = nontranslateprefix+value}
								if (isNote) textToNote(fpropName,obj,newvalue);  
								else obj.setProperty(fpropName,newvalue);
							}
					}									
				} else if (fprop.startsWith('*')) {
					// * sind in Bearbeitung nichts ersetzen
				} else if (fprop == "" && value == "" && ! notNull) {
					// das Ziel ist leer, der neue Wert auch und es ist kein Mussfeld. lass das Ziel leer
				} else if (fprop == "") {
					// das Ziel ist leer aber aus einem Grund muss ich es überschreiben (siehe vorheriges IF)
					// übersetze den Text. Falls es schief geht, mach daraus einen *XX* Text
					if (g_dotranslation){
						try {newvalue = '**'+translate(getCurrentLang(),flang,value)
							g_translatedentries++
							logtranslation(obj.getName(),propName,value, getCurrentLang(),newvalue ,flang)
							}
						catch (err) {newvalue = nontranslateprefix+value}
					}else {newvalue = nontranslateprefix+value}
					if (isNote) textToNote(fpropName,obj,newvalue);  
						else obj.setProperty(fpropName,newvalue);
			    } else {
					// das Ziel ist gefüllt (haben wir schon abgefragt), 
					// nicht in Bearbeitung und nicht automatisch übersetzt (* am Anfang haben wir schon abgefragt)
					// d.h. es hat einen gültigen Wert. 
					// Markiere es, falls die Quelle wirklich geändert hat (gegenüber dem current-Lang-Property)
					if (value != oldval && ! oldval.startsWith('*') && ! fprop.startsWith('*')) {
						// die Quelle hat geändert 
						// und war selber nicht ein Feld, das vor der Änderung einen * am Anfang hatte
						// und der foreign Wert hat noch kein * am Anfang
						// Markiere die foreign property
						if (isNote) textToNote(fpropName,obj,"*"+fprop);
					 	else obj.setProperty(fpropName,"*"+fprop);
						g_changedentries++
						logchangedvalue(obj.getName(),propName,fprop ,flang)
					}
				}
			}
		}
		// die Werte der CurrentLang kommen aus dem Objekt, überschreibe die Übersetzungsproperties immer
		if (isNote) textToNote(lpropName,obj,value);
		   else obj.setProperty(lpropName, value);
	}

	function doProperty(propName,obj,value,notNull){
		doLangValue(propName,obj,value,false,notNull);
	}

	function doNote(propName,obj,value) {
		doLangValue(propName,obj,value,true,false);
	}


	function fuellUDP(tolang){
		var ent
		var entities = model.getEntitySet().toArray();
		forEach(entities,function do1entity(ent,ie){
			doProperty("_ENTI_NAME",ent,ent.getName(),true)
			doNote("_ENTI_COMMENT",ent,ent.getComment())
			doProperty("_ENTI_SYNONYM",ent,ent.getSynonym(),false)

			if (tolang != null){
				ent.setName(ent.getProperty(tolang+"_ENTI_NAME"));
				ent.setComment(textFromNote(tolang+"_ENTI_COMMENT",ent))
				ent.setSynonym(ent.getProperty(tolang+"_ENTI_SYNONYM"));
			}

			forEach(ent.getAttributes().toArray(),
				function do1Attr(attr,idx){
					doProperty("_ATTR_NAME",attr,attr.getName(),true);
					doNote("_ATTR_COMMENT",attr,attr.getComment());			

					if (tolang != null){
						attr.setName(attr.getProperty(tolang+"_ATTR_NAME"));
						attr.setComment(textFromNote(tolang+"_ATTR_COMMENT",attr))
					}
				})
			ent.setDirty(true);
			}
		)


		//DEBUG				if (rel.getName() == '') linemessage(rel.getName(),rel.getNameOnSource());
		forEach(model.getRelationSet().toArray(), 
			function do1rela(rel,idx){
				doProperty("_RELA_TEXT_FROM",rel,rel.getNameOnSource(),false)
				doProperty("_RELA_TEXT_TO",rel,rel.getNameOnTarget(),false)	

				if (tolang != null){
					rel.setNameOnSource(rel.getProperty(tolang+"_RELA_TEXT_FROM"));
					rel.setNameOnTarget(rel.getProperty(tolang+"_RELA_TEXT_TO"));
				}
				//if (rel.getName() == '') linemessage('nachher',rel.getName(),rel.getNameOnSource());
				rel.setDirty(true);
			}
		)
	}

	function curDateStr(){
		var currentdate = new Date();
		return  currentdate.getDate() 
		+ "/" + (currentdate.getMonth()+1) 
		+ "/" + currentdate.getFullYear() + "  " 
		+ currentdate.getHours() + ":" 
		+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
	}

