	function changeLang(pfromLang,ptoLang){
		fuellUDP(ptoLang);
		setCurrentLang(ptoLang);
		setTranslInfo();	
		model.design.setDirty(true);
	}

	function selectcurlang(plangs){
		langs = []
		for (p in plangs){langs.push(plangs[p])}
		with (JavaGui) {
			var selected = JOptionPane.showInputDialog(null,
				"Choose your default language to start with","Languages",
				JOptionPane.QUESTION_MESSAGE, 
				null, langs,null);
			if (selected == null) {return null}
			selected = selected.substring(0,2)
			g_logger.logMessage("Default languages chosen: " + selected)
			return selected
		}
	}

	function selectlanguages(plangs){
		with (JavaGui) {
			list = new JList(plangs); //data has type Object[]
			list.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
			JOptionPane.showMessageDialog(null, list, "Choose your languages"
							,JOptionPane.INFORMATION_MESSAGE); 
			selvalues = list.getSelectedValuesList()
			if (selvalues.length == 0) {
				return null
			} else {
				g_logger.logMessage("languages chosen: " + selvalues)
			}
		}
		return selvalues
	}

	function initTranslation() {
		getTranslInfo()
		if (Object.keys(g_Params).length == 0) {
			langs = selectlanguages(availablelanguages)
			if (langs == null) {
				message ("TRANLSATION aborted as no languages were chosen");
				return
			}
			for (var i in langs) {
				if (i == 0) {langstext = langs[i].substr(0,2)}
				else {langstext += ','+langs[i].substr(0,2)}
			}
			setLanguages(langstext)
			curlang = selectcurlang(langs)
			if (curlang == null) {
				message ("TRANLSATION aborted as no current-language was chosen");
				return
			}
			setCurrentLang(curlang)
			setVersion(CODEVERSION)
			setDEEPLAuthKey("")
		} else {
			throw new Error("\n***TRANSLATION ("+getVersion()+") already installed***\n");
		}
		//hier gibt es einen Eintrag für die Translation
		init(false);

		fuellUDP(null);

		setTranslInfo()
		model.design.setDirty(true);
		message ("TRANLSATION installed current-language="+getCurrentLang()
			+ " languages="+getLanguages()+" version="+getVersion());
	}

	function changeLanguage() {
		var antwort
		init(false);
		var options = [];
		var langchangefrom = getCurrentLang()
		forEach(getLangArr(), 				
			function do1lang(lang,idx){
			if (lang != langchangefrom) {
				options.push(getCurrentLang() + '->' + lang)
				}
			}
		)
		if (options.length == 1) {
			antwort = options[0]
		} else {
			antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null, 
	        	"Choose language change",
				"Change language",
				QUESTIONMESSAGE,
				null, 
				options, 
				options[0]);
		}
        if (antwort != null){
			var toLang = antwort.substr(-2)
			//Java.type("javax.swing.JOptionPane").showMessageDialog(null, antwort+'|'+toLang);
			g_changedentries = 0
			g_translatedentries = 0
			//g_logger.logMessage("DEBUG: g_dotranslation="+g_dotranslation + "   tolang="+toLang);
			changeLang(getCurrentLang(),toLang);
			msg = "Model language changed from "+langchangefrom+" to "+toLang+".\n"+
					g_changedentries + " entries marked as changed.\n" +
					g_translatedentries + " entries translated."
			g_logger.logMessage(msg)
			linemessage (msg);
			setLabels(false)
			setLabels(true)
		}
	}

	function upgrade09_to_10() {
		forEach(model.getEntitySet().toArray(),
			function do1ent(ent,idx){
				forEach(getLangArr(),
					function do1lang(lang,idx){
						textToNote(lang+"_ENTI_COMMENT",ent,ent.getProperty(lang+"_ENTI_COMMENT"));

						forEach(ent.getAttributes().toArray(),
							function do1attr(attr,idx){
								textToNote(lang+"_ATTR_COMMENT",attr,attr.getProperty(lang+"_ATTR_COMMENT"));
							}
						)
				 	}
				)
			ent.setDirty(true);
			}
		)
	}
	function upgrade10_to_11() {
		// nothing to update so far
	}
	function upgrade11_to_12() {
		// nothing to update so far
	}
	function upgrade12_to_13() {
		// nothing to update so far
	}
	function upgrade13_to_14() {
		// add the empty translation key
		setDEEPLAuthKey("")
	}
	function upgrade14_to_15() {
		// add the empty translation key
	}
	function upgrade15_to_20() {
		// add the empty translation key
	}
	function upgrade20_to_21() {
		// empty fields are deleted in all elements
		forEach(model.getEntitySet().toArray(),
			function do1ent(ent,idx){
				forEach(getLangArr(),
					function do1lang(lang,idx){
						entcomm = ent.getComment()
						if (entcomm == "") textToNote(lang+"_ENTI_COMMENT",ent,"");
						entsyn = ent.getSynonym()
						if (entsyn == "") ent.setProperty(lang+"_ENTI_SYNONYM","");
						forEach(ent.getAttributes().toArray(),
							function do1attr(attr,idx){
								attrcomm = attr.getComment()
								if (attrcomm == "") textToNote(lang+"_ATTR_COMMENT",attr,"");
							}
						)
				 	}
				)
			ent.setDirty(true);
			}
		)
		forEach(model.getRelationSet().toArray(), 
			function do1rela(rel,idx){
				forEach(getLangArr(),
					function do1lang(lang,idx){
						relafrom = rel.getNameOnSource()
						if (relafrom == "") rel.setProperty(lang+"_RELA_TEXT_FROM","");
						relato = rel.getNameOnTarget()
						if (relato == "") rel.setProperty(lang+"_RELA_TEXT_TO","");
					}
				)
			}
		)
	}

	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (getVersion()  == CODEVERSION) {
			message("TRANSLATE: latest version ("+getVersion()+") is installed")
		} else {
			var upgraded = false
			if (getVersion() == "0.9") {
				upgrade09_to_10();
				upgraded = true
			}
			if (getVersion() == "1.0") {
				upgrade10_to_11();
				upgraded = true
			}
			if (getVersion() == "1.1") {
				upgrade11_to_12();
				upgraded = true
			}
			if (getVersion() == "1.2") {
				upgrade12_to_13();
				upgraded = true
			}
			if (getVersion() == "1.3") {
				upgrade13_to_14();
				upgraded = true
			}
			if (getVersion() == "1.4") {
				upgrade14_to_15();
				upgraded = true
			}
			if (getVersion() == "1.5") {
				upgrade15_to_20();
				upgraded = true
			}
			if (getVersion() == "2.0") {
				upgrade20_to_21();
				upgraded = true
			}
			if (upgraded) {
				setVersion(CODEVERSION)
				setTranslInfo();	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+getVersion()+").\n"
					+"Please contact support\n");
			}
		}			
	}

lib.script:
var CODEVERSION = "3.1";
			var FORMATJSON = "JSON";
			var FORMATCSV = "CSV"
			var g_tabanz = 0;
			var g_colanz = 0;
			var g_colmapanz = 0
			var g_tabmapanz = 0
			var g_lineanz = 0
			var g_logicalModel
			var g_entitySet
			var g_relationSet
			var g_inheritanceSet
			var g_rmodels
			var g_writtenCols = {}
			var g_exportDirec = java.lang.System.getProperty("user.home") +"/Downloads" 
			var g_importDirec = java.lang.System.getProperty("user.home") +"/Downloads"
			var EXTIDPROPNAME = "EXT_ATTR_ID"
			var EXCELCSVSEP = ";"
			var EXCELESCCHAR = '"'
			var EXCELMULTILINESEP = String.fromCharCode(10)
			var EXCELLINEEND = String.fromCharCode(10)
			var EXCELBOM = "\ufeff" //String.fromCharCode(0xef,0xbb,0xbf)
			var svlogger = model.getAppView() // messages to LOG
			function logMessage(){
				args = Array.prototype.slice.call(arguments,0);
				svlogger.logMessage(args.join(', '))
			}


			// Types for mapping element
			ENTITYPE = 0
			COLTYPE = 5
			TABLETYPE = 4
			ATTRTYPE = 1
			RELATYPE = 3 //(source ent, targ ent)
			FKTYPE = 8
			INHERITTYPE = 9
			RELARCTYPE = 13
			LOGARCTYPE = 14
			var g_containerMappings = {}
			var g_attrMappings = {}

			//ClassCollectionLoad
			var javaclasses = new JavaImporter(
				javax.swing.JOptionPane,
				javax.swing.JFileChooser,
				java.io.File,
				java.io.FileWriter,
				java.nio.file.Paths,
				java.nio.file.Files,
				java.nio.charset.StandardCharsets
				)
			//var Gui = new JavaImporter(java.awt, javax.swing);
			//with (Gui) {
			//    var awtframe = new Frame("AWT Frame");
			//    var jframe = new JFrame("Swing JFrame");
			//};

			var PLAINMESSAGE = 1;
			var ERRORMESSAGE = 0;
			var WARNINGMESSAGE = 2;
			var QUESTIONMESSAGE = 3;
			function fullmessage(msg, type) {
				//Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg, 'ODM-Translation', type);
				with(javaclasses) {
					JOptionPane.showMessageDialog(null, msg, 'ODM-Translation', type);
				}
			}

			function error(msg) {
				fullmessage(msg, ERRORMESSAGE);
			}

			function message(msg) {
				fullmessage(msg, PLAINMESSAGE);
			}

			function linemessage() {
				str = ''
				for (i=0;i<arguments.length;i++){
					str = str.concat(arguments[i],'\n')
				}
				message(str)
			}

			// simulates the not existing array.forEach method
			// for each element in arr, calls f(elem,idx)
			function forEach(arr,f){
				for (var idx = 0;idx < arr.length; idx++) { 
					f(arr[idx],idx);
				}
			}

			function getAllMappings(rmodels) {
				g_containerMappings = {}
				g_attrMappings = {}
				if (rmodels == null) return
				for (imod = 0; imod < rmodels.length; imod++) {
					rmod = rmodels[imod]
					modname = rmod.getName()
					tables = rmod.getTableSet()
					modelMap = rmod.getRMExtendedMap().getContainerMappings().toArray();
					if (modelMap != null) {
						for (imgm = 0; imgm < modelMap.length; imgm++) {
							logMap = modelMap[imgm]
							relName = tables.getObjectByID(logMap.getRelID())
							switch (logMap.getLogType()) {
								case ENTITYPE:
									logName = g_entitySet.getObjectByID(logMap.getLogID())
									break
								case RELATYPE:
									logName = g_relationSet.getObjectByID(logMap.getLogID())
									break;
								case INHERITTYPE:
									logName = g_inheritanceSet.getObjectByID(logMap.getLogID())
									break;
								default:
									logName = null
							}

							g_containerMappings[logMap.getID()] = {
								modelName: modname,
								logID: logMap.getLogID(),
								logName: logName,
								logType: logMap.getLogType(),
								relID: logMap.getRelID(),
								tableName: relName,
								relType: logMap.getRelType(),
								srcEntityID: logMap.getRealSourceEntityID(),
								trgEntityID: logMap.getRealTargetEntityID()
							}

							containedMaps = logMap.getContainedMappings()
							for (icm = 0; icm < containedMaps.length; icm++) {
								cm = containedMaps[icm]
								g_attrMappings[cm.getID()] = {
									modelName: modname,
									parentID: logMap.getID(),
									logID: cm.getLogID(),
									logType: cm.getLogType(),
									relID: cm.getRelID(),
									relType: cm.getRelType()
								}
							}
						}
					}
				}
			}

			function trimapo(s) {
				return s.replace(/^"|"$/g, '');
			}

			function curDateStr() {
				var currentdate = new Date();
				return currentdate.getDate() +
					"/" + (currentdate.getMonth() + 1) +
					"/" + currentdate.getFullYear() + "  " +
					currentdate.getHours() + ":" +
					currentdate.getMinutes() + ":" + currentdate.getSeconds();
			}

			function getContainerMaps(tabID) {
				maps = []
				for (key in g_containerMappings) {
					if (tabID == g_containerMappings[key].relID) maps.push(g_containerMappings[key])
				}
				return maps
			}

			function getContainerMap(entiID, tabID) {
				for (key in g_containerMappings) {
					if (tabID == g_containerMappings[key].relID && entiID == g_containerMappings[key].logID) return g_containerMappings[key]
				}
				return null
			}

			function getLogMap(logID, modName) {
				maps = []
				for (key in g_containerMappings) {
					if ((logID == g_containerMappings[key].logID) &&
						(modName == g_containerMappings[key].modelName)) maps.push(g_containerMappings[key])
				}
				return maps
			}

			function getColMaps(colID) {
				colsmap = []
				for (key in g_attrMappings) {
					//message(colID+'|'+cmap[icolmap].getRelID())
					if (colID == g_attrMappings[key].relID) colsmap.push(g_attrMappings[key])
				}
				return colsmap
			}

			function getColMap(colID, attrID) {
				for (key in g_attrMappings) {
					if (g_attrMappings[key].modelName == "--debug--") {
						message(key + '\n' + colID + '\n' + attrID + '\n' + g_attrMappings[key].relID + '\n' + g_attrMappings[key].logID)
					}
					if (colID == g_attrMappings[key].relID && attrID == g_attrMappings[key].logID) return g_attrMappings[key]
				}
				return null
			}

			// For the given Attribute, read the column mapping  in the modName
			function getAttrMap(attrID, relmodName) {
				attrmaps = []
				for (key in g_attrMappings) {
					//message(colID+'|'+cmap[icolmap].getRelID())
					if ((attrID == g_attrMappings[key].logID) &&
						(relmodName == g_attrMappings[key].modelName)
						) {
							attrmaps.push(g_attrMappings[key])
						}
				}
				return attrmaps
			}


			function getRelationAttribute(attrCollection, attrName) {
				for (grakey in attrCollection) {
					if (attrCollection[grakey].getName() == attrName) return attrCollection[grakey]
				}
				return null
			}

			function getRelationAttrByID(attrCollection, attrID) {
				for (grakey in attrCollection) {
					if (attrCollection[grakey].getObjectID() == attrID) return attrCollection[grakey]
				}
				return null
			}


			function do1line(values) {
				modelMapping = rmodel.getRMExtendedMap().getContainerMappings().toArray();
				tabName = values[0];
				colName = values[1];
				elemName = values[2];
				attrName = values[3];
				//linemessage(elemName,attrName,tabName,colName)
				relation = null
				entity = g_entitySet.getByName(elemName);
				if (entity != null) {
					attribute = entity.getElementByName(attrName);
				} else { // assume Relation 
					relation = g_relationSet.getByName(elemName)
					if (relation != null) {
						attribute = getRelationAttribute(relation.getAttributesCollection(), attrName);
					}
				}
				table = rmodel.getTableSet().getByName(tabName);
				// Neue Tabellen werden erzeugt
				if ((table == null) && (tabName != "")) {
					rmodel.createTable(tabName);
					table = rmodel.getTableSet().getByName(tabName);
					table.setComment("Created on " + curDateStr() + " during import from " + imppath)
					g_tabanz++
				}
				if (table != null) {
					column = table.getElementByName(colName);
				} else {
					column = null
				}
				// neue Columns werden erzeugt
				if ((column == null) && (colName != "")) {
					//linemessage('neue Column',colName,tabName)
					table.createColumn(colName)
					column = table.getElementByName(colName);
					column.setComment("Created on " + curDateStr() + " during import from " + imppath)
					g_colanz++
				}
				if ((entity != null) && (table != null)) {
					mapped = getContainerMap(entity.getObjectID(), table.getObjectID())
					if (mapped == null) {
						rmodel.getRMExtendedMap().createMapping(entity, table);
						g_tabmapanz++
					}
					if ((attribute != null) && (column != null)) {
						mapped = getColMap(column.getObjectID(), attribute.getObjectID())

						if (mapped == null) {
							rmodel.getRMExtendedMap().createMapping(attribute, column);
							g_colmapanz++
						}
					}
				}
				if ((relation != null) && (table != null)) {
					mapped = getContainerMap(relation.getObjectID(), table.getObjectID())
					if (mapped == null) {
						rmodel.getRMExtendedMap().createMapping(relation, table);
						g_tabmapanz++
					}
					if ((attribute != null) && (column != null)) {
						mapped = getColMap(column.getObjectID(), attribute.getObjectID())
						if (mapped == null) {
							rmodel.getRMExtendedMap().createMapping(attribute, column);
							g_colmapanz++
						}
					}
				}
			}

			function importFile(fpath) {
				with (javaclasses) {
					var lines = Files.readAllLines(Paths.get(fpath), StandardCharsets.UTF_8);
				}
				for (lnoif = 0; lnoif < lines.length; lnoif++) {
					line = lines[lnoif]
					values = line.split(";");
					for (iif = 0; iif < values.length; iif++) {
						values[iif] = trimapo(values[iif]);
					}
					if (lnoif == 0) {
						var relModel = values[0];
						// falls 1. Zeichen von Excel stammt, schneide es ab
						if (relModel.match(/^[^A-Za-z]/)) {relModel = relModel.substring(1)}
						rmodel = model.getDesign().getRelationalDesigns().getByName(relModel);
						if (rmodel == null) {
							throw new Error("\nRelational model '" + relModel + "' does not exist.\n");
						}
						getAllMappings([rmodel])
					} else
					if (lnoif == 1) {
						// skip headers
						//message(lnoif+': '+"headers= "+values);
					} else {
						//linemessage(lnoif,values.length,values);
						if (values.length>=4){
							do1line(values);
							g_lineanz++
						}
					}
				};
			}

			function importMapping() {
				//Create a file chooser
				with(javaclasses) {	
					//var Filebrowse = Java.type("javax.swing.JFileChooser");
					//f = new JFileChooser.Filebrowse(g_importDirec);
					f = new JFileChooser(g_importDirec);
					returnVal = f.showOpenDialog(null);
					if (returnVal == JFileChooser.APPROVE_OPTION) {
						imppath = f.getSelectedFile();
						//message(imppath);
					} else {
						return
					}
				}
				g_tabanz = 0
				g_colanz = 0
				g_colmapanz = 0
				g_lineanz = 0
				g_logicalModel = model.getDesign().getLogicalDesign();
				g_entitySet = g_logicalModel.getEntitySet()
				g_relationSet = g_logicalModel.getRelationSet()
				g_inheritanceSet = g_logicalModel.getInheritanceRelationSet()
				importFile(imppath);
				message("Parsed " + g_lineanz + " lines from file " + imppath + ".\n" +
						"Created " + g_tabanz + " tables, " + g_colanz + " columns,\n" +
						"Mapped " + g_tabmapanz + " tables to entities and " + g_colmapanz + " columns to attributes") // +tabmapanz+" table- and " 

			}

			function chooseModel() {
				if (g_rmodels.length == 0) throw new Error("\n***MAPPING: no relational models available ***\n");
				if (g_rmodels.length == 1) {
					antwort = g_rmodels[0]
				} else {
					rmodel = g_rmodels[0]
					with(javaclasses) {
						antwort = JOptionPane.showInputDialog(null,
							"Choose relational model",
							"choose model",
							QUESTIONMESSAGE,
							null,
							g_rmodels, rmodel);
					}
				}
				return antwort
			}

			function nvl(x) {
				return x == null ? "" : x
			}


			//read the mapping of a col to attributes
			// return list [['entyname',...],['attrname',[attrObjectId,...]
			function getcolattrmap(col){
				var retval = []
				var enties = []
				var attrs = []
				var ids = []
				colmaps = getColMaps(col.getObjectID())
				if (colmaps.length > 0) {
					// Column ist gemapped
					enties = []
					attrs = []
					ids = []
					for (impcm = 0; impcm < colmaps.length; impcm++) {
						curmap = colmaps[impcm]
						parentelem = g_containerMappings[curmap.parentID]
						var attr = null
						var attrId = null
						//DEBUG if (parentelem == null){message(tab.getName()+':'+curmap.logID)} //DEBUG
						//enties.push('a');attrs.push('b');ids.push('')

						switch (parentelem.logType) {
							case ENTITYPE:
								logElem = g_entitySet.getObjectByID(parentelem.logID)
								attr = logElem.getElementByID(curmap.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl(attr.getName()))
								ids.push(nvl(attr.getObjectID()))
								break;
							case RELATYPE:
								logElem = g_relationSet.getObjectByID(parentelem.logID)
								attr = getRelationAttrByID(logElem.getAttributesCollection(), curmap.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl(attr.getName()))
								ids.push(nvl(attr.getObjectID()))
								break;
							case INHERITTYPE:
								logElem = g_inheritanceSet().getObjectByID(parentelem.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl( '???'))
								ids.push('')
								break;
							default:
								logElem = '???'
								enties.push('???')
								attrs.push(nvl(parentelem.relType))
								ids.push('')
								//throw new Error("\n  Column'"+colkey +" unknown logical mapping type: "+parent.logType);
						}
					}
				}
				retval.push(enties,attrs,ids)
				return retval
			}

			function printColsMap(tab) {
				cols = tab.getElementsCollection().toArray()
				g_writtenCols = {}
				attrentry = []
				for (icpcm = 0; icpcm < cols.length; icpcm++) {
					col = cols[icpcm]
					colkey = tab + '.' + col

					//		//FK mapped to Relations
					//		if (col.isFKColumn()) {
					//			fks = col.getAllFKs()
					//			for (ifk=0;ifk<fks.length;ifk++){
					//				fkID=fks[ifk].getObjectID()
					//				fkmaps = getContainerMaps(fkID)
					////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ifk+' :1: '+fkID+' : '+fkmaps.length)
					//				for (ir=0;ir<fkmaps.length;ir++){
					//					rela = g_relationSet.getObjectByID(fkmaps[ir].logID)
					////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ir+' :2: '+fkmaps[ir].logID+':'+rela)
					//					if (rela == null) rela = g_inheritanceSet.getObjectByID(fkmaps[ir].logID)	
					////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ir+' :3: '+rela)
					//					writeMapLine(fw,tab,rela,col, null)
					//					g_writtenCols[colkey]=true
					//				}
					//			}
					//		}

					colmaps = getColMaps(col.getObjectID())
					if (colmaps.length > 0) {
						// Column ist gemapped
						for (impcm = 0; impcm < colmaps.length; impcm++) {
							curmap = colmaps[impcm]
							parentelem = g_containerMappings[curmap.parentID]
							//DEBUG if (parentelem == null){message(tab.getName()+':'+curmap.logID)} //DEBUG
							switch (parentelem.logType) {
								case ENTITYPE:
									logElem = g_entitySet.getObjectByID(parentelem.logID)
									attrName = logElem.getElementByID(curmap.logID).getName()
									break;
								case RELATYPE:
									logElem = g_relationSet.getObjectByID(parentelem.logID)
									attrName = getRelationAttrByID(logElem.getAttributesCollection(), curmap.logID).getName()
									break;
								case INHERITTYPE:
									logElem = g_inheritanceSet().getObjectByID(parentelem.logID)
									attrName = '???'
									break;
								default:
									logElem = '???'
									attrName = parentelem.relType
										//throw new Error("\n  Column'"+colkey +" unknown logical mapping type: "+parent.logType);
							}
							attrentry.push( [tab.getName(),(col == null)?'' : col.getName(),nvl(logElem.getName()),nvl(attrName)])

							g_writtenCols[colkey] = true
						}
					}
					//Jede Column wird mind. 1x geschrieben.
					if (!g_writtenCols[colkey]) {attrentry.push( [tab.getName(),col.getName(),'',''])}
				}
				return attrentry
			}
			function booltoX(b){
				return b ? 'X' : ''
			}

			//get all info and mappings for developpers output into an attributelist
			function gatherDevCols(relModel) {
				//attrlist is a list of columns to be outputted as a line of ; seaparated fields in the final csv
				//it has to contain as many entries, as the headers in allmapping in the calling function
				var attrlist = []

				//print all tables and columns for 1 relational model
				var tables = relModel.getTableSet().toArray();
				//for every table in this relmodel
				for (var itpc = 0; itpc < tables.length; itpc++) {
					var tab = tables[itpc]

					//for all columns in the current table
					var cols = tab.getElementsCollection().toArray()
					for (var icpcm = 0; icpcm < cols.length; icpcm++) {
						var col = cols[icpcm]

						var colkey = tab + '.' + col

						//start with the entry for the current model table/column
						var mycolentry = [tab.getName(),col.getName(),colProperty(relModel, tab.getName(), col.getName(), EXTIDPROPNAME)
										,col.getDatatypeText(),booltoX(col.isMandatory()),col.getDefaultValue()
										,col.getComment(),col.getNotes()
										]

						//add the Logical model mapping in the format ['enti\nenti\nenti','attr\nattr\nattr']
						var colattrs = getcolattrmap(col)										
						mycolentry.push(colattrs[0],colattrs[1])

						//linemessage(2,attrlist.length,tab.getName(),col.getName(),mycolentry.length)

						var attrids = colattrs[2]
						// alle relationalen Modelle ausser dem aktuellen 
						var restrmodels = []
						var emptycols = []
						var allindirectcols = {}
						for (r = 0; r < g_rmodels.length; r ++){
							if (g_rmodels[r] != relModel.getName()) {
								restrmodels.push(g_rmodels[r])
								emptycols.push([],[],[])
								allindirectcols[g_rmodels[r].getName()] = [[],[],[]] 
							}
						} 

						if (attrids.length == 0) {
							mycolentry = mycolentry.concat(emptycols)
						} else {
							// for all attributes mapped to the current column,
							// get all columns mapped to them
							for (i = 0; i < attrids.length; i ++){
								// add to the line all mappings from the attribute to all columns in the other models
								var attrid = attrids[i]
								if (attrid != null) {
									attrelements = modelAttrElements(restrmodels, attrid)
									// {modelname : [[tabname,],[colname,],[id,]]}
									//logMessage('===== attrelements',JSON.stringify(attrelements,undefined,2))
									for (modelName in attrelements){
										//logMessage('=== ' , modelName, '===',JSON.stringify(attrelements[modelName][0],undefined,2),JSON.stringify(attrelements[modelName][1],undefined,2),JSON.stringify(attrelements[modelName][2],undefined,2))
										allindirectcols[modelName][0] = allindirectcols[modelName][0].concat(attrelements[modelName][0])
										allindirectcols[modelName][1] = allindirectcols[modelName][1].concat(attrelements[modelName][1])
										allindirectcols[modelName][2] = allindirectcols[modelName][2].concat(attrelements[modelName][2])
									}
								}
							}
							//logMessage(JSON.stringify(allindirectcols,undefined,2))
							for (modelName in allindirectcols){
								mycolentry = mycolentry.concat(allindirectcols[modelName])
							}	
							//logMessage(JSON.stringify(mycolentry,undefined,2))
						}
						attrlist.push(mycolentry)
					}
				}
				return attrlist
			}

			function gatherCols(relModel) {
				tables = relModel.getTableSet().toArray();
				var attrlist = []
				for (itpc = 0; itpc < tables.length; itpc++) {
					tab = tables[itpc]

					containermaps = getContainerMaps(tab.getObjectID())
					if (containermaps.length == 0) {
						attrlist = attrlist.concat(printColsMap(tab))
					} else {
						//print entity/relation - Mapping of Table
						for (impc = 0; impc < containermaps.length; impc++) {
							switch (containermaps[impc].logType) {
								case ENTITYPE:
									enti = g_entitySet.getObjectByID(containermaps[impc].logID)
									if (enti != null) attrlist.push([tab.getName(), '', enti.getName(),''])
									break;
								case RELATYPE:
									rela = g_relationSet.getObjectByID(containermaps[impc].logID)
									if (rela != null) attrlist.push([tab.getName(), '',rela.getName(),''])
									break;
								case INHERITTYPE:
									//		inher=g_inheritanceSet().getObjectByID(containermaps[impc].logID)
									//		if (inher != null) writeMapLine(fw,tab,inher,null,null)
									break;
								default:
									throw new Error("\n  Table'" + tab +
										" unknown logical mapping type: " + containermaps[impc].logType);
							}
						}
						attrlist = attrlist.concat(printColsMap(tab))
					}
				}
				return attrlist
			}

			function chooseFile(direc, fileName) {
				//Create a file chooser
				//message("direc= "+direc)
				with(javaclasses) {	
					f = new JFileChooser(direc);
					f.setSelectedFile(new File(fileName));
					returnVal = f.showOpenDialog(null);
					if (returnVal == JFileChooser.APPROVE_OPTION) {
						return f.getSelectedFile();
					} else {
						return null
					}
				}
			}

			function createFile(fileName) {
				//Create a file chooser
				with (javaclasses) {
					fw = new FileWriter(fileName);
				}
				return fw
			}


			function getColName(rmod, tabID, colID) {
				tab = rmod.getTableSet().getObjectByID(tabID)
				col = tab.getElementByID(colID)
				return tab + '.' + col
			}

			function colProperty(pcurmodel, tabname, colname, propName) {
				table = pcurmodel.getTableSet().getByName(tabname);
				if (table == null) return ""
				column = table.getElementByName(colname);
				extID = column.getProperty(propName)
				return ((extID == null) || (extID == ".")) ? "" : extID
			}

			function findFK(fks, fkID) {
				for (iloc in fks) {
					//		if (fkID == "8AEA1CA4-3B90-4F1D-37AE-8A0FD50F8996") {message(fks[iloc].getTable()+fks[iloc].getObjectID()+fks[iloc])}
					if (fks[iloc].getObjectID() == fkID) return fks[iloc]
				}
				return null
			}

			function tabList(maps, elemType, pcurmodel) {
				tlretval = []
				if (maps != null) {
					if (elemType != 'Entity') {
						fks = pcurmodel.getFKIndexAssociationSet().toArray()
					}
					for (i in maps) {
						if (elemType == 'Entity') {
							tabName = maps[i].tableName
						} else {
							fk = findFK(fks, maps[i].relID)
							if (fk != null) {
								tabName = fk.getTable()
							} else {
								tabName = maps[i].tableName // falls es m:n ist ist es eine Table
							}
						}
						tlretval.push(tabName.getName())
					}
				}
				//message('tablist= '+tlretval+ '|'+elemType)
				return tlretval
			}

			function elements(rmodels, logID, elemType, nurX) {
				elretval = []
				for (ih = 0; ih < rmodels.length; ih++) {
					var curmodel = rmodels[ih]
					maps = getLogMap(logID, curmodel)
					if (maps.length > 0) {
						if (nurX) {
							elretval.push(['X'])
						} else {
							elretval.push(tabList(maps, elemType, curmodel), [], [])
						}
					} else {
						if (nurX) {
							elretval.push([])
						} else {
							elretval.push([], [], [])
						}
					}
					// Extra columns are empty
				}
				return elretval
			}

			var g_curmodel = null // for the sortattrmaps function			
			function sortattrmaps(a,b){
				var atab = g_containerMappings[a.parentID].tableName
				var acol = g_curmodel.getTableSet().getByName(atab).getElementByID(a.relID)
				var btab = g_containerMappings[b.parentID].tableName
				var bcol = g_curmodel.getTableSet().getByName(btab).getElementByID(b.relID)
				if (a.modelName < b.modelName) {return -1 }
				if (a.modelName > b.modelName) {return 1 }
				if (atab < btab) {return -1 }
				if (atab > btab) {return 1}
				return (acol < bcol) ? -1 : (acol > bcol) ? 1 : 0
			}

			function attrElements(rmodels, attrID, nurX) {
				var aeretval = []
				var attrlist = []
				var tabNames = []
				var colNames = []
				var colIDs = []
				for (irmpm = 0; irmpm < rmodels.length; irmpm++) {
					g_curmodel = rmodels[irmpm]

					var attrmaps = getAttrMap(attrID, g_curmodel.getName())
					if (attrmaps.length > 0) {
						// NICHT NOETIG attrmaps.sort(sortattrmaps)
						if (nurX) {
							attrlist = [
								['X']
							]
						} else {
							attrlist = [],
							tabNames = []
							colNames = []
							colIDs = []
							var attrmaplist = []
							for (var key in attrmaps) {
							    attrmaplist.push( attrmaps[key] );
							}											

							for (var amidx=0;amidx<attrmaplist.length;amidx++) {
								var attrmap = attrmaplist[amidx]
								tabName = g_containerMappings[attrmap.parentID].tableName
								colName = g_curmodel.getTableSet().getByName(tabName).getElementByID(attrmap.relID)
								tabNames.push(tabName.getName())
								colNames.push(colName.getName())
								colIDs.push(colProperty(g_curmodel, tabName, colName, EXTIDPROPNAME))
							}

							//tabNames = tabNames.slice(0, -1)
							//colNames = colNames.slice(0, -1)
							//colIDs = colIDs.slice(0, -1)
							attrlist = [tabNames, colNames, colIDs]
						}
					} else {
						attrlist = nurX ? [
							[]
						] : [
							[],
							[],
							[]
						]
					}
					aeretval = aeretval.concat(attrlist)
				}
				return aeretval
			}

			function modelAttrElements(rmodels, attrID) {
				var aeretval = {}
				var attrlist = []
				var tabNames = []
				var colNames = []
				var colIDs = []
				for (irmpm = 0; irmpm < rmodels.length; irmpm++) {
					g_curmodel = rmodels[irmpm]

					var attrmaps = getAttrMap(attrID, g_curmodel.getName())
					if (attrmaps.length > 0) {
						// NICHT NOETIG attrmaps.sort(sortattrmaps)
						attrlist = [],
						tabNames = []
						colNames = []
						colIDs = []
						var attrmaplist = []
						for (var key in attrmaps) {
						    attrmaplist.push( attrmaps[key] );
						}											

						for (var amidx=0;amidx<attrmaplist.length;amidx++) {
							var attrmap = attrmaplist[amidx]
							tabName = g_containerMappings[attrmap.parentID].tableName
							colName = g_curmodel.getTableSet().getByName(tabName).getElementByID(attrmap.relID)
							tabNames.push(tabName.getName())
							colNames.push(colName.getName())
							colIDs.push(colProperty(g_curmodel, tabName, colName, EXTIDPROPNAME))
						}

						//tabNames = tabNames.slice(0, -1)
						//colNames = colNames.slice(0, -1)
						//colIDs = colIDs.slice(0, -1)
						attrlist = [tabNames, colNames, colIDs]
					} else {
						attrlist = [
							[],
							[],
							[]
						]
					}
					aeretval[g_curmodel.getName()] = attrlist
				}
				return aeretval
			}

			function logicalElement(rmodels, logElem, nurX) {
				var leretval = []
				var elemID = logElem.getObjectID()
				var attrs = null
				var entyentry 
				if (logElem.getObjectTypeName() == 'Entity') {
					entyentry = [logElem.getName(), '']
					entyentry = entyentry.concat(elements(rmodels, logElem.getObjectID(), logElem.getObjectTypeName(), nurX))
					leretval.push(entyentry)
					attrs = logElem.getElementsCollection().toArray()
				} else if (logElem.getObjectTypeName() == 'Relation') {
					if (logElem.isManyToMany()) { // FK-Mapping ist nicht trivial bei seltsamen Modellen
						entyentry = [logElem.getName(), '']
						entyentry = entyentry.concat(elements(rmodels, logElem.getObjectID(), logElem.getObjectTypeName(), nurX))
						leretval.push(entyentry)
						attrs = logElem.getAttributesCollection().toArray()
					}
				} else { // assume inheritance
					// Inheritance sind schon entities line += elements(rmodels,logElem.getObjectID(),logElem.getObjectTypeName(),nurX)
					// Inheritance becomes fk-columns
				}
				//message('logical Elements before attrs= '+logElem.getName()+'|'+leretval)
				if (attrs != null) {
					for (iattrac = 0; iattrac < attrs.length; iattrac++) {
						var attr = attrs[iattrac]
						var attrID = attr.getObjectID()
						var key = elemID + '.' + attrID
						attrentry = [logElem.getName(), attr.getName()] //DEBUG  ,attrID]
						attrentry = attrentry.concat(attrElements(rmodels, attrID, nurX))
						leretval.push(attrentry)
							//throw new Error("\nattrs: " + leretval + "\n");
					}
				}
				//message('logical Elements= '+logElem.getName()+'|'+leretval)
				return leretval
			}

			function mappings2json(rmodels, group, nurX) {
				m2jretval = []
				if (group != null) {
					for (ig = 0; ig < group.length; ig++) {
						m2jretval = m2jretval.concat(logicalElement(rmodels, group[ig], nurX))
					}
				}
				return m2jretval
			}

			// replace " by ', enclose string between "" if it contains lf
			function escapeexcelchars(s){
				var retval = s.replace(/"/g, "'") //  " sollte EXCELESCCHAR sein ist aber umständlich
				if (retval.match(/\n/)) {retval = EXCELESCCHAR + retval + EXCELESCCHAR}
				return retval
			}

			// print a line (list of entries) as a lf-separated list enclosed between ""
			// if there is a " in the string, replace it
			function printline(fw, line) {
				forEach(line,
					function print1ine(field,idx){
						if (idx > 0) {
							fw.write(EXCELCSVSEP)
						}
						try {
							if (typeof field == 'string') {
								fw.write(escapeexcelchars(field) )
							} else if (field.length == 0) {
								fw.write('') // empty List
							} else if (field.length == 1) {
								fw.write(escapeexcelchars(field[0])) // single string in List
							} else {
								// list of Strings
								fw.write(escapeexcelchars(field.join(EXCELMULTILINESEP)) )
							}
						} catch (err) {linemessage(typeof field, field,line); throw err}
					}
				)				
				fw.write(EXCELLINEEND)
			}

			//print entries as possible list of entries
			function printlines(fw, entry) {
				for (ie = 0; ie < entry.length; ie++) {
					line = entry[ie]
						// es ist eine Liste von Zeilen
					printline(fw, line)
				}
			}

			// output jsonstructure in allMapping iin csv-format
			function json2csv(fw, allMapping) {
				fw.write(EXCELBOM)
				for (key in allMapping) {
					entry = allMapping[key]
					switch (key) {
						case "model":
						case "header":
						case "subheader":
							fw.write(entry.join(EXCELCSVSEP))
							fw.write(EXCELLINEEND)
							break;
						case "attrlist":
							printlines(fw, entry)
							break;
						case "footer":
							fw.write(entry)
							fw.write(EXCELLINEEND)
							break;
						default:
							fw.write('unbekannter Eintrag ' + key)
					}
				}
			}

			// gather globals for all needed elements
			function gatherModel() {
				g_logicalModel = model.getDesign().getLogicalDesign();
				g_entitySet = g_logicalModel.getEntitySet()
				g_relationSet = g_logicalModel.getRelationSet()
				g_inheritanceSet = g_logicalModel.getInheritanceRelationSet()
				g_rmodels = model.getDesign().getRelationalDesigns().toArray();
			}

			// all data is collected in allmapping
			// print it to json or transform it into csv
			function printjson(fw, format, allmapping) {
				switch (format) {
					case FORMATJSON:
						fw.write(JSON.stringify(allmapping, null, 2)); // spacing level = 2)
						break;
					case FORMATCSV:
						// transform json structure into csv and print it
						json2csv(fw, allmapping)
						break;
					default:
						throw new Error("invalid format " + format)
				}
			}

			// print matrix of Entities/Attributes to tables or tables/columns
			// format-> CSV or JSON
			// fw -> open file
			// nurX -> True: only existence in table (X), False: with columnnames
			function printMatrix(fw, nurX, format) {
				// Read complete model into globals
				gatherModel()

				//read all mappings of all models into
				getAllMappings(g_rmodels)

				if (nurX) {
					allmapping = {
						"header": ['entity', 'attr']
					}
					for (ih = 0; ih < g_rmodels.length; ih++) {
						allmapping["header"].push(g_rmodels[ih].getName())
					}
				} else {
					allmapping = {
						"header": ['Information model', ''],
						"subheader": ['entity', 'attr']
					}
					for (ih = 0; ih < g_rmodels.length; ih++) {
						allmapping["header"].push(g_rmodels[ih].getName(), '', '')
						allmapping["subheader"].push('table', 'column', 'ID')
					}
				}

				//throw new Error("\nheaders: " + allmapping["header"] + "\n");
				allmapping["attrlist"] = mappings2json(g_rmodels, g_entitySet.toArray(), nurX)
				allmapping["attrlist"] = allmapping["attrlist"].concat(mappings2json(g_rmodels, g_relationSet.toArray(), nurX))

				allmapping["footer"] = 'created by ODM, ' + curDateStr();
				printjson(fw, format, allmapping)
			}

			function printCVS(fw, format,relModel) {

				// lies alle Mappings des gewählten Modells
				getAllMappings([relModel])
				allmapping = {
					"model": [relModel.getName(), '', 'Information model', ''],
					"header": ['tableName', 'columnName','entityName', 'attrName'],
					"attrlist": gatherCols(relModel)
				}
				printjson(fw, format, allmapping)
			}

			//prints a developpers CVS for one relmodel
			// starting with information about the tables/columns continuing with mapping to IM and other relmodels.
			function printDevCVS(fw, format,relModel) {
				// lies alle Mappings des gewählten Modells
				mymodelname = relModel.getName()
				// prepare jsonstructure for Header and data
				allmapping = {
					"model": [mymodelname,'','','','','','','', 'Information model',''],
					"header": ['tableName', 'columnName','ID','datatype','mand.','def. value','descr','rules','entity','attribute'],
					"attrlist": gatherDevCols(relModel)
				}

				// Add all relational models except myself to the header
				for (ih = 0; ih < g_rmodels.length; ih++) {
					if (g_rmodels[ih].getName() != mymodelname) {
						//linemessage(ih,g_rmodels[ih].getName(), mymodelname)
						allmapping["model"].push(g_rmodels[ih].getName(), '', '')
						allmapping["header"].push('table','column','ID')
					}
				}

				// add all other models into the allmapping-structure and print it
				printjson(fw, format, allmapping)
			}

			//choose outputfilepath. Default = pfilename
			function chooseoutputfilename(pfilename, pformat) {
				fileName = chooseFile(g_exportDirec, pfilename +
					((pformat == FORMATJSON) ?'.js' : ((pformat == FORMATCSV) ?'.csv' :'txt')))
				return fileName
			}

			// ask and return the output format (CSV / JSON)
			function outputformat() {
				var formatauswahl = [FORMATJSON, FORMATCSV]
				with(javaclasses) {
					antwort = JOptionPane.showInputDialog(null,
						"Output format",
						"choose output format",
						QUESTIONMESSAGE,
						null,
						formatauswahl, FORMATCSV);
				}
				return antwort
			}

			//print mapping for one relmodel to the IM
			// tables/columuns to entities/attributes
			// This csv will be imported later to set mappings
			function print1Mapping() {
				gatherModel()
				var relModel = chooseModel();
				if (relModel == null) return;

				format = outputformat()
				if (format == null) {
					return 
				}
				filename = chooseoutputfilename(relModel.getName(), format)
				if (filename == null) {
					return 
				} else {
					fw = createFile(filename)
				}
				printCVS(fw, format,relModel)
				fw.close();
				message("Mapping file " + fileName + " for model " + relModel.getName() + " created.");
			}

			//Print developpers mapping for one relmodel
			//some information about every column
			// followed by informationmodel Entitiy/Attribute
			// followed by (indirect via IM) mapping to other systems tables/columns
			function printDevMapping() {
				gatherModel()
				// select 1 relmodel
				var relModel = chooseModel();
				if (relModel == null) return;

				//select the output format (CSV,JSON)
				format = outputformat()
				if (format == null) {
					return null
				}
				//define and open file
				filename = chooseoutputfilename(relModel.getName()+'_dev', format)
				if (filename == null) {
					return
				} else {
					fw = createFile(filename)
				}
				// read all mappings for all relmodels
				getAllMappings(g_rmodels)
				//print developers excel for the chosen relmodel
				printDevCVS(fw, format,relModel)
				fw.close();
				message("Mapping file " + fileName + " for model " + relModel.getName() + " created.");
			}


			// Print matrix of Entities/Attributes to Tables or tables/columns of all relational systems
			// Mappings are read within the printMatrix
			// nurX -> only X for existence in table
			// not nurX -> print name of attributes
			function printAllMapping(nurX) {
				format = outputformat()
				if (format == null) {
					return null
				}
				filename = model.getDesign().getName()
				filename = chooseoutputfilename(filename + (nurX ? 'X' : ''), format)
				if (filename == null) {
					return
				} else {
					fw = createFile(filename)
				}
				printMatrix(fw, nurX, format)
				fw.close();
				message("Mapping file " + fileName + " created.");
			}

			// Print matrix of Entities/Attributes to Tables of all relational systems
			// print only existence (X) 
			function printXMapping() {
				printAllMapping(true)
			}

			// Print matrix of Entities/Attributes to Tables/Columns of all relational systems
			// print names of mapping (can be multiline)
			function printNameMapping() {
				printAllMapping(false)
			}

			// Autoren: aro, stb
// Functions:
// createsubview - creates a new subview (according to entered zoomlevel) based on the current subview + executes "showhideelements" at the end
// showhideelements - logs all visibility errors according to defined zoomlevel and displayed parentsubview
// initzoomlevel - set only "not set" zoomlevel definitions according standardrules

//InitVars begin
var CODEVERSION = '0.2'
var PLAINMESSAGE = 1
var ERRORMESSAGE = 0
var WARNINGMESSAGE = 2
var QUESTIONMESSAGE = 3

var g_minzoomlevel = 0
var g_maxzoomlevel = 4
var g_logger = model.getAppView()
//InitVars end

//HelperFunctions start
function fullmessage(msg,type) {
    Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg,'ODM-Message', type)
}

function promptmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showInputDialog(null, msg,'ODM-Promtbox', type)
    return retval
}

function confirmmessage(msg,type) {
    var retval = Java.type("javax.swing.JOptionPane").showConfirmDialog(null, msg,'ODM-Confirmbox', type)
    if (retval == 0) {
        return true
    }else{
        return false
    }
}

function error(msg) {
    fullmessage(msg,ERRORMESSAGE)
}

function message(msg) {
    fullmessage(msg,PLAINMESSAGE)
}

function prompt(msg){
    var retval = promptmessage(msg,QUESTIONMESSAGE)
    return retval
}

function confirm(msg){
    var retval = confirmmessage(msg,0)
    return retval
}

function isNumeric(n) {
    return !isNaN(parseFloat(n)) && isFinite(n)
}
//HelperFunctions end

//LogicalFunctions start
function getsubview(thissv){
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    var retval = null
    for (var vv=0;vv<svlist.length;vv++){
        var checksv = svlist[vv]
        if (((thissv == null) && (checksv.isCurrentDPV())) || (thissv == checksv)) {
            retval = checksv
            break
        }
    }
    return retval
}

function getcommentvalue(srcobj,srcvalue){      
    var retval = null
    var commentlines = []
    commentlines = srcobj.getComment().split("\n")
    for (var vv=0;vv<commentlines.length;vv++){
        if (commentlines[vv].contains(srcvalue+"=")){
            retval = commentlines[vv].replace(srcvalue+"=","").trim()
            break
        }
    }
    if (((retval == null) || (retval == "")) && (srcvalue == "zoomlevel")) {
        retval = g_minzoomlevel
        message("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
        g_logger.logMessage("No "+srcvalue+" definition in view \""+srcobj+"\" found! The default value \""+g_minzoomlevel+"\" was used!")
    }
    return retval
}

function getzoomlevelprompt(){
    var retval = prompt('Choose desired zoomlevel')
    if ((!(isNumeric(retval))) || (retval > g_maxzoomlevel) || (retval < g_minzoomlevel)) {
        error("ERROR: No correct zoomlevel entered")
        g_logger.logMessage("ERROR: No correct zoomlevel entered")
        retval = null
    }
    return retval
}

function getMinMax(checkObj){
    g_minzl = checkObj.getProperty("minzoomlevel")  
    g_maxzl = checkObj.getProperty("maxzoomlevel")
    if ((!(isNumeric(g_minzl))) || (g_minzl < g_minzoomlevel)){
        g_minzl = g_minzoomlevel
        g_logger.logMessage("No correct zoomlevel (min) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }
    if ((!(isNumeric(g_maxzl))) || (g_maxzl > g_maxzoomlevel)){
        g_maxzl = g_maxzoomlevel
        g_logger.logMessage("No correct zoomlevel (max) definition found on element \""+checkObj+"\" ("+checkObj.getObjectTypeName()+")")
    }    
}
function checkSetDescAttr(checkObj){
    var thisdescflag = checkObj.getProperty("isdescriptive")
    if (thisdescflag == ""){
        thisdescflag = "FALSE"
        var keys = checkObj.getEntity().getUniqueIdentifiers()
        for (var ik=0;ik<keys.length;ik++){
            key = keys[ik]
            var attrkeys = key.getElementsCollection()
            for (var ik2=0;ik2<attrkeys.length;ik2++){
                var attrkey = attrkeys[ik2]
                if (attrkey == checkObj){
                    thisdescflag = "TRUE"
                    break
                }
            }
        }            
        checkObj.setProperty("isdescriptive", thisdescflag)
    }
}

function calcnewMinMax(checkObj){
    //DEV
    checkObj.setProperty("minzoomlevel","")  
    checkObj.setProperty("maxzoomlevel","")  
    checkObj.setProperty("isdescriptive","")  
    //DEV

    var minzl = checkObj.getProperty("minzoomlevel")  
    var maxzl = checkObj.getProperty("maxzoomlevel")  
    var newminzl = g_minzoomlevel
    var newmaxzl = g_maxzoomlevel
    switch(checkObj.getObjectTypeName().toString()){
        case "Entity":
            var attrs = checkObj.getAttributes().toArray()
            var relas = checkObj.getRelations().toArray()
            //DEV Not Root?
            var haschildren = false
            for (var ir=0;ir<relas.length;ir++){
                var rela = relas[ir]
                if (rela.getSourceEntity() == checkObj){
                    haschildren = true
                    break
                }
            }
            if ((attrs.length == 0) && (!(haschildren))){
                newmaxzl = 1
            }else if((attrs.length > 0) && (!(haschildren))){
                var hasdescattr = false
                for (var ia=0;ia<attrs.length;ia++){
                    var attr = attrs[ia]
                    checkSetDescAttr(attr)
                    if (attr.getProperty("isdescriptive") == "TRUE"){
                        hasdescattr = true
                    }
                }
                if (!(hasdescattr)){
                    newmaxzl = 2
                }
            }
            break
        case "Attribute":
            checkSetDescAttr(checkObj)
            var thisdescflag = checkObj.getProperty("isdescriptive")
            if (thisdescflag == "FALSE") {
                newmaxzl = 0
            }else{
                newmaxzl = 2
            }
            break
    }
    g_logger.logMessage("DEV: Set \""+checkObj+"\" ("+checkObj.getObjectTypeName()+") min/max to: "+newminzl+"/"+newmaxzl)
    if (!(isNumeric(minzl))){
        //DEV
        //checkObj.setProperty("minzoomlevel",newminzl)      
    }
    if ((!(isNumeric(maxzl))) || ((maxzl == g_maxzoomlevel) && (maxzl != newmaxzl))) {
        //DEV
        //checkObj.setProperty("maxzoomlevel",newmaxzl)
    }
}

function addChildrenToList(svObj, entityList, entityObj, checkzl){  
    var entityChildren = entityObj.getHierarchicalChildren()
    for (var ic=0;ic<entityChildren.length;ic++){
        var entityChild = entityChildren[ic]
        getMinMax(entityChild)
        if (!((checkzl > g_maxzl) || (checkzl < g_minzl))){    
            var thistv0 = entityChild.getFirstViewForDPV(svObj)
            if (thistv0 != null){
                var thiscell0 = thistv0.getCellView().getCell()
                entityList.push(thiscell0)
                if (entityChild.getHierarchicalChildrenCount() > 0) {
                    entityList = addChildrenToList(svObj, entityList, entityChild, checkzl)
                }
            }
        }
    }
    return entityList
}
//LogicalFunctions end

//createsubview start
function createsubview(){
    var sv = getsubview(null)
    var newzlevel = getzoomlevelprompt()
    if ((sv == null) || (newzlevel == null)){
        return
    }
    var sventities = sv.getTVShapes()
    var list = []
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function createsubview")

    //Mark all hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalRoot() == true)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){               
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Mark all non-hierarchical elements with the appropriate zoomlevel
    for (var ie=0;ie<sventities.length;ie++){
        var sventity = sventities[ie]
        var thisentity = model.getEntitySet().getByName(sventity)
        if ((thisentity != null) && (thisentity.isHierarchicalEntityType() == false)) {
            getMinMax(thisentity)
            if (!((newzlevel > g_maxzl) || (newzlevel < g_minzl))){       
                var tv0 = thisentity.getFirstViewForDPV(sv)
                var cell0 = tv0.getCellView().getCell()
                list.push(cell0)
                list = addChildrenToList(sv, list, thisentity, newzlevel)
            }
        }
    }
    //Create new subview & cleanup (rename, set comment, show elements, hide attributes)
    sv.getWorkSpace().setSelectionCells(list)
    sv.createSubViewFromSelected()
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    for (var vv=0;vv<svlist.length;vv++){
        var newsv = svlist[vv]
        if (newsv.isCurrentDPV()) {            
            newsv.setName(sv+"_ZL"+newzlevel)
            newsv.setComment("zoomlevel="+newzlevel+"\nparentview="+sv)
            newsv.setShowLegend(sv.showLegend())
            newsv.setShowLabels(sv.showLabels())
            newsv.setShowRelAttributes(sv.showRelAttributes())
            newsv.setShowGrid(sv.showGrid())
            newsv.setShowPageGrid(sv.showPageGrid())
            var newsventities = newsv.getTVShapes()
            for (var ie=0;ie<newsventities.length;ie++){
                var newsventity = newsventities[ie]
                var newentity = model.getEntitySet().getByName(newsventity)
                if (newentity != null) {
                    if (newentity.getName() == newsventity){          
                        var attrs = newentity.getAttributes().toArray()
                        for (var ia=0;ia<attrs.length;ia++) {
                            var attr = attrs[ia]
                            getMinMax(attr)
                            var hiddenElements = newsventity.getHiddenElements()
                            var isOnSVEntity = true
                            for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                                var hiddenElement = hiddenElements[ia2]
                                if (attr == hiddenElement){
                                    isOnSVEntity = false
                                }
                            }
                            if (((newzlevel > g_maxzl) || (newzlevel < g_minzl)) && (isOnSVEntity)){
                                if (!(newsventity.isHideElementsInCurrentOnly())){
                                    newsventity.setHideElementsInCurrentOnly(true)
                                }
                                hiddenElements.add(attr)
                            }
                        }
                    }
                }
            }
        }
    }
    g_logger.logMessage("End function createsubview")
    showhideelements()    
}
//createsubview start

//showhideelements start
function showhideelements(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function showhideelements")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    var sv = getsubview(null)
    var sventities = sv.getTVShapes()
    var svrelations = sv.getTVConnectors()
    var svzlevel = getcommentvalue(sv,"zoomlevel")
    var svpview = getcommentvalue(sv,"parentview")
    var haspv = false
    if ((svpview != null) && (svpview != "")){
        haspv = true
        var pv = getsubview(svpview)
        var pvzlevel = getcommentvalue(pv,"zoomlevel")
        var pventities = pv.getTVShapes()
        var pvrelations = pv.getTVConnectors()    
    }
    var NoOfDifZL = 0
    var NoOfDifPV = 0
    var logPrefix = ""

    //Zoomlevelcheck entity begin
    logPrefix = "ZoomLevelCheck > Entity"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    var showAttributes = []
    var hideAttributes = []    
    for (var ie = 0; ie < entities.length; ie++){
        var entity = entities[ie]
        var isOnSV = false
        for (var ie2=0;ie2<sventities.length;ie2++){
            var sventity = sventities[ie2]
            if (entity.getName() == sventity){
                isOnSV = true               
                var attrs = entity.getAttributes().toArray()
                for (var ia=0;ia<attrs.length;ia++) {
                    var attr = attrs[ia]
                    getMinMax(attr)
                    var isOnSVEntity = true
                    var hiddenElements = sventity.getHiddenElements()
                    for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                        var hiddenElement = hiddenElements[ia2]
                        if (attr == hiddenElement){
                            isOnSVEntity = false
                            break
                        }
                    }
                    if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)) {
                        if (isOnSVEntity) {
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+attr)
                            NoOfDifZL++
                        }
                    }else{
                        if (!(isOnSVEntity)){
                            showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)    
                            NoOfDifZL++
                        }
                    }
                }    
                break                         
            }
        }
        getMinMax(entity)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+entity)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+entity)
                NoOfDifZL++
            }
        }
    }
    for (var i=0;i<showElements.length;i++){
        g_logger.logMessage(showElements[i])
    }
    for (var i=0;i<hideElements.length;i++){
        g_logger.logMessage(hideElements[i])
    }
    for (var i=0;i<showAttributes.length;i++){
        g_logger.logMessage(showAttributes[i])
    }
    for (var i=0;i<hideAttributes.length;i++){
        g_logger.logMessage(hideAttributes[i])
    }
    //Zoomlevelcheck entity end

    //Zoomlevelcheck relation begin
    logPrefix = "ZoomLevelCheck > Relation"
    g_logger.logMessage(logPrefix)
    var showElements = []
    var hideElements = []
    for (var ir = 0; ir < relations.length; ir++){
        var relation = relations[ir]
        var isOnSV = false
        for (var ir2=0;ir2<svrelations.length;ir2++){
            var svrelation = svrelations[ir2]
            if (relation.getName() == svrelation){
                isOnSV = true
                break
            }
        }
        getMinMax(relation)
        if ((svzlevel > g_maxzl) || (svzlevel < g_minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+relation)
                NoOfDifZL++
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+relation)
                NoOfDifZL++
            }
        }
    }   
    for (var is=0;is<showElements.length;is++){
        g_logger.logMessage(showElements[is])
    }
    for (var ih=0;ih<hideElements.length;ih++){
        g_logger.logMessage(hideElements[ih])
    }
    //Zoomlevelcheck relation end

    //Parentviewcompare entity begin
    if (haspv){
        logPrefix = "ParentViewCompare > Entity"
        g_logger.logMessage(logPrefix)
        var showAttributes = []
        var hideAttributes = []
        for (var ie = 0; ie < pventities.length; ie++){
            var pventity = pventities[ie]
            var entity = model.getEntitySet().getByName(pventity)
            var thissventity = null
            var isOnSV = false
            for (var ie2=0;ie2<sventities.length;ie2++){
                var sventity = sventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnSV = true
                    thissventity = sventity
                    break
                }
            }
            if (!(isOnSV)){            
                if (entity != null){
                    getMinMax(entity)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+entity)
                        NoOfDifPV++
                    }
                }
            }else{
                var pvhiddenElements = pventity.getHiddenElements()
                var svhiddenElements = thissventity.getHiddenElements()
                for (var ih=0;ih<pvhiddenElements.length;ih++){
                    var pvhiddenElement = pvhiddenElements[ih]
                    getMinMax(pvhiddenElement)
                    if (!((pvzlevel > g_maxzl) || (pvzlevel < g_minzl))) {
                        for (var ih2=0;ih2<svhiddenElements.length;ih2++){
                            if (pvhiddenElements[ih] == svhiddenElements[ih2]){
                                isOnSV = false
                                break
                            }
                        }
                        if (isOnSV){
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+pvhiddenElements[ih])
                            NoOfDifPV++
                        } 
                    }
                }
                if (entity != null){
                    var attrs = entity.getAttributes().toArray()
                    for (var ia=0;ia<attrs.length;ia++) {
                        var attr = attrs[ia]
                        getMinMax(attr)
                        var isOnPV = true
                        if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)) {
                            for (var ih=0;ih<pvhiddenElements.length;ih++){
                                if (pvhiddenElements[ih] == attr){
                                    isOnPV = false
                                    break
                                }
                            }
                            if (isOnPV){
                                isOnSV = true
                                for (var ih=0;ih<svhiddenElements.length;ih++){
                                    if (svhiddenElements[ih] == attr){
                                        isOnSV = false
                                        break
                                    }
                                }
                                if (!(isOnSV)){
                                    showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)
                                    NoOfDifPV++
                                }
                            }
                        }
                    }        
                }
            }
        }
        for (var ie = 0; ie < sventities.length; ie++){
            var sventity = sventities[ie]
            var isOnPV = false
            for (var ie2=0;ie2<pventities.length;ie2++){
                var pventity = pventities[ie2]
                if (pventity.toString() == sventity.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+sventity) 
                NoOfDifPV++
            }
        }
        for (var i=0;i<showAttributes.length;i++){
            g_logger.logMessage(showAttributes[i])
        }
        for (var i=0;i<hideAttributes.length;i++){
            g_logger.logMessage(hideAttributes[i])
        }
        //Parentviewcompare entity end

        //Parentviewcompare relation begin
        logPrefix = "ParentViewCompare > Relation"
        g_logger.logMessage(logPrefix)
        for (var ir = 0; ir < pvrelations.length; ir++){
            var pvrelation = pvrelations[ir]
            var isOnSV = false
            for (var ir2=0;ir2<svrelations.length;ir2++){
                var svrelation = svrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnSV = true
                    break
                }
            }
            if (!(isOnSV)){
                var relation = model.getRelationSet().getByName(pvrelation)
                if (relation != null){
                    getMinMax(relation)
                    if ((pvzlevel > g_maxzl) || (pvzlevel < g_minzl)){
                        g_logger.logMessage(logPrefix+" > SHOW: "+pvrelation)
                        NoOfDifPV++
                    }
                }
            }
        }
        for (var ir = 0; ir < svrelations.length; ir++){
            var svrelation = svrelations[ir]
            var isOnPV = false
            for (var ir2=0;ir2<pvrelations.length;ir2++){
                var pvrelation = pvrelations[ir2]
                if (pvrelation.toString() == svrelation.toString()){
                    isOnPV = true
                    break
                }
            }
            if (!(isOnPV)){
                g_logger.logMessage(logPrefix+" > HIDE: "+svrelation)
                NoOfDifPV++
            }
        }
    }else{
        g_logger.logMessage("CHECK: No comparison of the parent view due to missing ABC definition")
    }
    //Parentviewcompare relation end   
    var finalmessage = "Showhideelements result:"
    if (NoOfDifZL > 0){
        finalmessage += "\n"+NoOfDifZL+" differences to zoomlevel definition found!"
    }
    if (NoOfDifPV > 0){
        finalmessage += "\n"+NoOfDifPV+" differences to parentview definition found!"
    }
    if ((NoOfDifPV == 0) && (NoOfDifZL == 0)){
        finalmessage += "\nNo differences found."
    }else{
        finalmessage += "\nPlease check log-messages."
    }
    message(finalmessage)
    g_logger.logMessage("End function showhideelements")       
} 
//showhideelements end

//initzoomlevel start
function initzoomlevel(){
    g_logger.logMessage("\n")
    g_logger.logMessage("Start function initzoomlevel")
    var entities = model.getEntitySet().toArray()
    var relations = model.getRelationSet().toArray()
    //setMinMax to entities
    for (var ie=0;ie<entities.length;ie++){
        var entity = entities[ie]
        calcnewMinMax(entity)
        //setMinMax to attributes of entity
        var attrs = entity.getAttributes().toArray()
        for (var ia=0;ia<attrs.length;ia++) {
            var attr = attrs[ia]
            calcnewMinMax(attr)
        }
    }
    /*
    //setMinMax to relations
    for (var ir=0;ir<relations.length;ir++){
        var relation = relations[ir]
        calcnewMinMax(relation)
    }
    */
    g_logger.logMessage("End function initzoomlevel")
}
//initzoomlevel end

